using System.Buffers.Binary;
using System.Globalization;
using System.Text;
using System.Text.Json;

namespace MxoHd.PacketResearch;

public static class ReportWriter
{
    private const uint AbilityCodeFlag = 0x80000000;
    private const uint AbilityCodeMask = 0xfffffc00;
    private const uint AbilityLevelMask = 0x000003ff;

    private static readonly HashSet<uint> FullPriceAbilityCodes = new()
    {
        2148365312, // BalanceAbility
        2147490816, // DetectVulnerabilityAbility
        2147605504, // DisarmTrapsAbility
        2147492864, // EnergizedAttacksAbility
        2147496960, // HyperStrengthAbility
        2147684352, // IgnorePainAbility
        2147858432, // ImpartInvisibilityAbility
        2147497984, // PowerShotAbility
        2147499008, // PreciseBlowAbility
        2147500032, // PunishingBlowsAbility
        2148372480, // PurityAbility
        2148374528, // SpinningFlowerAbility
        2148373504, // SweepTheFloorAbility
        2148364288, // TechniqueAbility
        2148375552 // ZenMasterAbility
    };

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        WriteIndented = true
    };

    public static void WriteJson(PacketResearchReport report, string path)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        File.WriteAllText(path, JsonSerializer.Serialize(report, JsonOptions));
    }

    public static void WriteMarkdown(PacketResearchReport report, string path)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path))!);
        File.WriteAllText(path, ToMarkdown(report));
    }

    public static string ToMarkdown(PacketResearchReport report)
    {
        StringBuilder builder = new();
        builder.AppendLine("# Packet Research Summary");
        builder.AppendLine();
        builder.AppendLine("Generated by `tools/PacketResearch`. This file summarizes packet evidence without copying raw dump bodies into the report.");
        builder.AppendLine();
        builder.AppendLine("## Inputs");
        builder.AppendLine();
        builder.AppendLine($"- Repository: `{report.RepositoryRoot}`");
        builder.AppendLine($"- Packet dump roots: {FormatList(report.PacketDumpRoots)}");
        builder.AppendLine($"- Rajko MxOEmu source: `{report.RajkoSourceRoot ?? "not provided"}`");
        builder.AppendLine($"- External source roots: {FormatList(report.ExternalSourceRoots)}");
        builder.AppendLine();

        int packetLines = report.PacketDumpFiles.Sum(file => file.PacketLikeLines);
        builder.AppendLine("## Totals");
        builder.AppendLine();
        builder.AppendLine($"- Local RPC headers: {report.LocalHeaders.Count}");
        builder.AppendLine($"- Local attribute definitions: {report.AttributeDefinitions.Count}");
        builder.AppendLine($"- Imported FX definitions: {report.FxDefinitions.Count}");
        builder.AppendLine($"- Imported ability definitions: {report.AbilityDefinitions.Count}");
        builder.AppendLine($"- Imported animation definitions: {report.AnimationDefinitions.Count}");
        builder.AppendLine($"- Game object symbol entries: {report.GameObjectEntries.Count}");
        builder.AppendLine($"- Inventory command item entries: {report.ItemCommandEntries.Count}");
        builder.AppendLine($"- Static object correlation rows: {report.StaticObjectEntries.Count}");
        builder.AppendLine($"- World entity rows: {report.WorldEntityEntries.Count}");
        builder.AppendLine($"- Rajko RPC dispatch entries: {report.RajkoRpcHeaders.Count}");
        builder.AppendLine($"- Hardcoded command examples: {report.HardcodedCommands.Count}");
        builder.AppendLine($"- Hardcoded protocol 03 examples: {report.HardcodedProtocol03Examples.Count}");
        builder.AppendLine($"- External object-interaction command examples: {report.Protocol04InteractionCommandExamples.Count}");
        builder.AppendLine($"- Vendor inventory rows: {report.VendorInventoryEntries.Count}");
        builder.AppendLine($"- Protocol 04 interaction payloads: {report.PacketDumpFiles.Sum(file => file.Protocol04InteractionPayloads.Count)}");
        builder.AppendLine($"- Protocol 04 top-level vendor transaction flows: {report.PacketDumpFiles.Sum(file => file.VendorTransactionFlows?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 additional server payload shape samples: {report.PacketDumpFiles.Sum(file => file.Protocol04ServerPayloadShapes?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 unknown `81 67` payloads: {report.PacketDumpFiles.Sum(file => file.Unknown8167Payloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 unknown `47` payloads: {report.PacketDumpFiles.Sum(file => file.Unknown47Payloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 unknown `6d` payloads: {report.PacketDumpFiles.Sum(file => file.Unknown6dPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 unknown `80 c1` payloads: {report.PacketDumpFiles.Sum(file => file.Unknown80c1Payloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 load-world payloads: {report.PacketDumpFiles.Sum(file => file.LoadWorldPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 player value payloads: {report.PacketDumpFiles.Sum(file => file.PlayerValuePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 flash traffic payloads: {report.PacketDumpFiles.Sum(file => file.FlashTrafficPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 feature/event payloads: {report.PacketDumpFiles.Sum(file => file.FeatureEventPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 faction/player-info payloads: {report.PacketDumpFiles.Sum(file => file.FactionPlayerInfoPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 crew-member payloads: {report.PacketDumpFiles.Sum(file => file.CrewMembersListPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 friend-online payloads: {report.PacketDumpFiles.Sum(file => file.FriendOnlinePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 chat message response payloads: {report.PacketDumpFiles.Sum(file => file.ChatMessageResponsePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 whereami response payloads: {report.PacketDumpFiles.Sum(file => file.WhereamiResponsePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 faction-name response payloads: {report.PacketDumpFiles.Sum(file => file.FactionNameResponsePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 ability unload payloads: {report.PacketDumpFiles.Sum(file => file.AbilityUnloadPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 friend list status payloads: {report.PacketDumpFiles.Sum(file => file.FriendListStatusPayloads?.Count ?? 0)}");
        builder.AppendLine($"- Protocol 04 coder attribute payloads: {report.PacketDumpFiles.Sum(file => file.CoderAttributePayloads?.Count ?? 0)}");
        builder.AppendLine($"- Packet dump files with packet-like lines: {report.PacketDumpFiles.Count}");
        builder.AppendLine($"- Packet-like lines: {packetLines}");
        builder.AppendLine();

        AppendRajkoComparison(builder, report);
        AppendPacketDumpSummary(builder, report);
        AppendProtocol04InteractionSummary(builder, report);
        AppendProtocol04InteractionCommandExamples(builder, report);
        AppendStaticObjectCorrelations(builder, report);
        AppendVendorInventoryCorrelations(builder, report);
        AppendProtocol04SequenceSummary(builder, report);
        AppendUnknown8167PayloadSummary(builder, report);
        AppendUnknown47PayloadSummary(builder, report);
        AppendUnknown6dPayloadSummary(builder, report);
        AppendUnknown80c1PayloadSummary(builder, report);
        AppendLoadWorldPayloadSummary(builder, report);
        AppendPlayerValuePayloadSummary(builder, report);
        AppendFlashTrafficPayloadSummary(builder, report);
        AppendFeatureEventPayloadSummary(builder, report);
        AppendFactionPlayerInfoPayloadSummary(builder, report);
        AppendCrewMembersListPayloadSummary(builder, report);
        AppendFriendOnlinePayloadSummary(builder, report);
        AppendChatMessageResponsePayloadSummary(builder, report);
        AppendWhereamiResponsePayloadSummary(builder, report);
        AppendFactionNameResponsePayloadSummary(builder, report);
        AppendProtocol04ServerPayloadShapeSummary(builder, report);
        AppendProtocol03ObjectViewSummary(builder, report);
        AppendProtocol03SelectorFfRepeatListResourceReferences(builder, report);
        AppendProtocol03SelectorFfRepeatListDecodedRows(builder, report);
        AppendProtocol03SelectorFfRepeatListShapeSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListEffectiveShapeSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListEntryPairSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListContinuationMarkerSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListContinuationParserActionSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListParserCoverageSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorContinuationBodyOffsetSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorPrePositionBodyOffsetSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBodyWindowProbeSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBodyWindowParserActionSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBodyWindowEvidenceSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBodyWindowResourceCollisionSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListEffectiveShapeHeaderSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListHeaderNameSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListHeaderRegionSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBoundaryDecisionRows(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBoundaryPrioritySummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBoundaryInterpretationSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListVendorBoundaryTargetSummaries(builder, report);
        AppendProtocol03SelectorFfRepeatListHeaderSamples(builder, report);
        AppendProtocol03SelectorFfRepeatListLayoutSummaries(builder, report);
        AppendHardcodedProtocol03Examples(builder, report);
        AppendPlayerAttributePayloadSummary(builder, report);
        AppendAbilityUnloadPayloadSummary(builder, report);
        AppendFriendListStatusPayloadSummary(builder, report);
        AppendCoderAttributePayloadSummary(builder, report);
        AppendManageBonusPayloadSummary(builder, report);
        AppendVendorSignals(builder, report);

        return builder.ToString();
    }

    private static void AppendRajkoComparison(StringBuilder builder, PacketResearchReport report)
    {
        if (report.RajkoComparisons.Count == 0)
        {
            builder.AppendLine("## Rajko RPC Dispatch Map");
            builder.AppendLine();
            builder.AppendLine("No Rajko source root was provided, so no external dispatch map was compared.");
            builder.AppendLine();
            return;
        }

        builder.AppendLine("## Rajko RPC Dispatch Map");
        builder.AppendLine();
        builder.AppendLine("| External raw | Handler | Match | Local header | Local name |");
        builder.AppendLine("| --- | --- | --- | --- | --- |");
        foreach (RpcComparison comparison in report.RajkoComparisons)
        {
            builder.AppendLine(
                $"| `{comparison.External.RawHeader}` | `{comparison.External.Handler}` | {comparison.MatchKind} | `{comparison.Local?.EncodedHeader ?? "-"}` | {comparison.Local?.Name ?? "-"} |");
        }

        builder.AppendLine();
    }

    private static void AppendPacketDumpSummary(StringBuilder builder, PacketResearchReport report)
    {
        builder.AppendLine("## Packet Dump Coverage");
        builder.AppendLine();
        if (report.PacketDumpFiles.Count == 0)
        {
            builder.AppendLine("No packet dumps were parsed.");
            builder.AppendLine();
            return;
        }

        Dictionary<string, int> protocolTotals = new(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, int> rpcTotals = new(StringComparer.OrdinalIgnoreCase);
        Dictionary<string, int> knownHeaderTotals = new(StringComparer.OrdinalIgnoreCase);
        foreach (PacketDumpFileSummary file in report.PacketDumpFiles)
        {
            AddCounts(protocolTotals, file.ProtocolCounts);
            AddCounts(rpcTotals, file.RpcHeaderCounts);
            AddCounts(knownHeaderTotals, file.KnownHeaderCounts);
        }

        builder.AppendLine("### Protocol Counts");
        builder.AppendLine();
        builder.AppendLine("| Protocol | Lines |");
        builder.AppendLine("| --- | ---: |");
        foreach ((string protocol, int count) in protocolTotals.OrderByDescending(entry => entry.Value))
        {
            builder.AppendLine($"| `{protocol}` | {count} |");
        }

        builder.AppendLine();
        builder.AppendLine("### Protocol 04 Header Hits");
        builder.AppendLine();
        if (rpcTotals.Count == 0)
        {
            builder.AppendLine("No protocol 04 headers were detected with the current heuristic.");
            builder.AppendLine();
        }
        else
        {
            builder.AppendLine("| Header | Count |");
            builder.AppendLine("| --- | ---: |");
            foreach ((string header, int count) in rpcTotals.OrderByDescending(entry => entry.Value).ThenBy(entry => entry.Key))
            {
                builder.AppendLine($"| `{header}` | {count} |");
            }

            builder.AppendLine();
        }

        builder.AppendLine("### Embedded Known Header Candidates");
        builder.AppendLine();
        builder.AppendLine("This scan searches every packet-like line for known two-byte local headers. Treat these as leads for manual decoding, not proof that the surrounding bytes are fully understood.");
        builder.AppendLine();
        if (knownHeaderTotals.Count == 0)
        {
            builder.AppendLine("No embedded known headers were detected.");
            builder.AppendLine();
        }
        else
        {
            builder.AppendLine("| Header | Count |");
            builder.AppendLine("| --- | ---: |");
            foreach ((string header, int count) in knownHeaderTotals.OrderByDescending(entry => entry.Value).ThenBy(entry => entry.Key).Take(30))
            {
                builder.AppendLine($"| `{header}` | {count} |");
            }

            builder.AppendLine();
        }

        builder.AppendLine("### Largest Parsed Files");
        builder.AppendLine();
        builder.AppendLine("| File | Packet-like lines | Protocol 04 hits | Embedded header candidates |");
        builder.AppendLine("| --- | ---: | ---: | ---: |");
        foreach (PacketDumpFileSummary file in report.PacketDumpFiles.OrderByDescending(file => file.PacketLikeLines).Take(15))
        {
            builder.AppendLine($"| `{file.File}` | {file.PacketLikeLines} | {file.RpcHeaderCounts.Values.Sum()} | {file.KnownHeaderCounts.Values.Sum()} |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol04InteractionSummary(StringBuilder builder, PacketResearchReport report)
    {
        Protocol04InteractionWithFile[] interactions = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04InteractionPayloads.Select(payload => new Protocol04InteractionWithFile(file.File, payload)))
            .ToArray();

        if (interactions.Length == 0)
        {
            return;
        }

        builder.AppendLine("## Protocol 04 Object Interaction Payloads");
        builder.AppendLine();
        builder.AppendLine("This decodes the payload shape used by the local object-interaction handlers: four-byte object id, two-byte sector window from that id, and one-byte object type. Type names are local handler labels, so they are interaction leads rather than complete protocol semantics.");
        builder.AppendLine();
        builder.AppendLine("| Header | Kind | Object type | Local type label | Count | Distinct object ids | Sample | Sample payload |");
        builder.AppendLine("| --- | --- | ---: | --- | ---: | ---: | --- | --- |");
        foreach (var group in interactions
            .GroupBy(entry => new
            {
                entry.Payload.RawHeader,
                entry.Payload.InteractionKind,
                entry.Payload.ObjectType,
                entry.Payload.ObjectTypeName
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.RawHeader)
            .ThenBy(group => group.Key.ObjectType))
        {
            Protocol04InteractionWithFile sample = group.First();
            builder.AppendLine(
                $"| `{group.Key.RawHeader}` | {group.Key.InteractionKind} | {group.Key.ObjectType} | {group.Key.ObjectTypeName} | {group.Count()} | {group.Select(entry => entry.Payload.ObjectId).Distinct().Count()} | `{sample.File}:{sample.Payload.Line}` | `{sample.Payload.PayloadHex}` |");
        }

        builder.AppendLine();

        builder.AppendLine("### Repeated Interaction Object IDs");
        builder.AppendLine();
        builder.AppendLine("| Object id | Sector | Kind | Object type | Local type label | Count | Sample |");
        builder.AppendLine("| ---: | ---: | --- | ---: | --- | ---: | --- |");
        foreach (var group in interactions
            .GroupBy(entry => new
            {
                entry.Payload.ObjectId,
                entry.Payload.SectorId,
                entry.Payload.InteractionKind,
                entry.Payload.ObjectType,
                entry.Payload.ObjectTypeName
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.ObjectId)
            .Take(25))
        {
            Protocol04InteractionWithFile sample = group.First();
            builder.AppendLine(
                $"| {group.Key.ObjectId} | {group.Key.SectorId} | {group.Key.InteractionKind} | {group.Key.ObjectType} | {group.Key.ObjectTypeName} | {group.Count()} | `{sample.File}:{sample.Payload.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol04InteractionCommandExamples(StringBuilder builder, PacketResearchReport report)
    {
        if (report.Protocol04InteractionCommandExamples.Count == 0)
        {
            return;
        }

        builder.AppendLine("## External Object Interaction Command Examples");
        builder.AppendLine();
        builder.AppendLine("These parse raw `HandleCommand:` debug lines from external MxOEmu source/log artifacts. They are not full packet captures, but they preserve client RPC command bytes that can validate object-interaction payload shape.");
        builder.AppendLine();
        builder.AppendLine("| Header | Kind | Object type | Local type label | Count | Distinct object ids | Sample | Sample payload |");
        builder.AppendLine("| --- | --- | ---: | --- | ---: | ---: | --- | --- |");
        foreach (var group in report.Protocol04InteractionCommandExamples
            .GroupBy(entry => new
            {
                entry.RawHeader,
                entry.InteractionKind,
                entry.ObjectType,
                entry.ObjectTypeName
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.RawHeader)
            .ThenBy(group => group.Key.ObjectType))
        {
            Protocol04InteractionCommandExample sample = group.First();
            builder.AppendLine(
                $"| `{group.Key.RawHeader}` | {group.Key.InteractionKind} | {group.Key.ObjectType} | {group.Key.ObjectTypeName} | {group.Count()} | {group.Select(entry => entry.ObjectId).Distinct().Count()} | `{sample.Source} {sample.File}:{sample.Line}` | `{sample.PayloadHex}` |");
        }

        builder.AppendLine();
        builder.AppendLine("### Repeated External Interaction Object IDs");
        builder.AppendLine();
        builder.AppendLine("| Object id | Sector | Kind | Object type | Local type label | Count | Sample |");
        builder.AppendLine("| ---: | ---: | --- | ---: | --- | ---: | --- |");
        foreach (var group in report.Protocol04InteractionCommandExamples
            .GroupBy(entry => new
            {
                entry.ObjectId,
                entry.SectorId,
                entry.InteractionKind,
                entry.ObjectType,
                entry.ObjectTypeName
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.ObjectId)
            .Take(25))
        {
            Protocol04InteractionCommandExample sample = group.First();
            builder.AppendLine(
                $"| {group.Key.ObjectId} | {group.Key.SectorId} | {group.Key.InteractionKind} | {group.Key.ObjectType} | {group.Key.ObjectTypeName} | {group.Count()} | `{sample.Source} {sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendStaticObjectCorrelations(StringBuilder builder, PacketResearchReport report)
    {
        if (report.StaticObjectEntries.Count == 0)
        {
            return;
        }

        Dictionary<uint, int> dumpInteractionCounts = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04InteractionPayloads)
            .GroupBy(payload => payload.ObjectId)
            .ToDictionary(group => group.Key, group => group.Count());
        Dictionary<uint, int> externalCommandCounts = report.Protocol04InteractionCommandExamples
            .GroupBy(example => example.ObjectId)
            .ToDictionary(group => group.Key, group => group.Count());
        Dictionary<uint, int> vendorRowCounts = report.VendorInventoryEntries
            .GroupBy(entry => entry.VendorStaticId)
            .ToDictionary(group => group.Key, group => group.Count());
        ILookup<int, GameObjectEntry> gameObjectsById = report.GameObjectEntries.ToLookup(entry => entry.GoId);

        builder.AppendLine("## Static Object Table Correlations");
        builder.AppendLine();
        builder.AppendLine("This joins decoded object-interaction object ids against tracked `data/staticObjects_*.csv` rows using the same little-endian `mxoId` decoding as the runtime static object loader. Multiple rows for one object id are important evidence: they can indicate duplicate old static rows, district/sector reuse, or local type ambiguity that must be resolved before assigning final object-interaction semantics.");
        builder.AppendLine();
        builder.AppendLine("| Object id | Packet-dump interactions | External command interactions | Static rows | Vendor rows | Sectors | Type ids / symbols | Position samples | Sample static row |");
        builder.AppendLine("| ---: | ---: | ---: | ---: | ---: | --- | --- | --- | --- |");

        foreach (var group in report.StaticObjectEntries
            .GroupBy(entry => entry.MxoId)
            .OrderByDescending(group => dumpInteractionCounts.GetValueOrDefault(group.Key) + externalCommandCounts.GetValueOrDefault(group.Key))
            .ThenBy(group => group.Key))
        {
            StaticObjectEntry sample = group.First();
            string sectors = FormatDistinct(group.Select(entry => $"{entry.MetrId}/{entry.SectorId}"), 8);
            string types = FormatCandidateList(group
                .GroupBy(entry => entry.TypeId)
                .OrderByDescending(typeGroup => typeGroup.Count())
                .ThenBy(typeGroup => typeGroup.Key)
                .Select(typeGroup =>
                {
                    string[] symbols = gameObjectsById[typeGroup.Key]
                        .Select(entry => FormatTableText(entry.CodeName))
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                        .Take(3)
                        .ToArray();
                    string symbolText = symbols.Length == 0
                        ? "-"
                        : string.Join(", ", symbols);
                    return $"{typeGroup.Key} {symbolText} ({typeGroup.Count()})";
                })
                .ToArray());
            string positions = FormatDistinct(group.Select(FormatStaticObjectPosition), 4);

            builder.AppendLine(
                $"| {group.Key} | {dumpInteractionCounts.GetValueOrDefault(group.Key)} | {externalCommandCounts.GetValueOrDefault(group.Key)} | {group.Count()} | {vendorRowCounts.GetValueOrDefault(group.Key)} | {sectors} | {types} | {positions} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendVendorInventoryCorrelations(StringBuilder builder, PacketResearchReport report)
    {
        if (report.VendorInventoryEntries.Count == 0)
        {
            return;
        }

        Dictionary<uint, int> dumpInteractionCounts = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04InteractionPayloads)
            .GroupBy(payload => payload.ObjectId)
            .ToDictionary(group => group.Key, group => group.Count());
        Dictionary<uint, int> externalCommandCounts = report.Protocol04InteractionCommandExamples
            .GroupBy(example => example.ObjectId)
            .ToDictionary(group => group.Key, group => group.Count());
        Dictionary<uint, ItemCommandEntry> itemsById = BuildItemCommandDictionary(report.ItemCommandEntries);
        HashSet<uint> interactionObjectIds = new(dumpInteractionCounts.Keys.Concat(externalCommandCounts.Keys));
        VendorInventoryEntry[] matches = report.VendorInventoryEntries
            .Where(entry => interactionObjectIds.Contains(entry.VendorStaticId))
            .ToArray();
        if (matches.Length == 0)
        {
            return;
        }

        builder.AppendLine("## Vendor Inventory Object Correlations");
        builder.AppendLine();
        builder.AppendLine("This joins decoded object-interaction object ids against tracked `data/vendor_items.csv` rows. The vendor list was parser-derived from old logs and is incomplete, so a match is a lead that the static id may be vendor-related, not proof of a complete vendor exchange.");
        if (itemsById.Count > 0)
        {
            builder.AppendLine("Item samples are resolved through the imported MxOEmu `&gib` command list when possible.");
        }

        builder.AppendLine();
        builder.AppendLine("| Static object id | Metr ids | Vendor rows | Packet-dump interactions | External command interactions | Item counts | Sample items | Sample vendor row |");
        builder.AppendLine("| ---: | --- | ---: | ---: | ---: | --- | --- | --- |");
        foreach (var group in matches
            .GroupBy(entry => entry.VendorStaticId)
            .OrderByDescending(group => dumpInteractionCounts.GetValueOrDefault(group.Key) + externalCommandCounts.GetValueOrDefault(group.Key))
            .ThenBy(group => group.Key))
        {
            VendorInventoryEntry sample = group.First();
            string metrIds = string.Join(", ", group.Select(entry => entry.MetrId).Distinct().OrderBy(value => value));
            string itemCounts = string.Join(", ", group.Select(entry => entry.Items.Count).Distinct().OrderBy(value => value));
            string sampleItems = FormatItemReferences(group.SelectMany(entry => entry.Items).Distinct().Take(8), itemsById);
            builder.AppendLine(
                $"| {group.Key} | {metrIds} | {group.Count()} | {dumpInteractionCounts.GetValueOrDefault(group.Key)} | {externalCommandCounts.GetValueOrDefault(group.Key)} | {itemCounts} | {sampleItems} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol04SequenceSummary(StringBuilder builder, PacketResearchReport report)
    {
        var sequences = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04PacketSequences.Select(sequence => new Protocol04SequenceWithFile(file.File, sequence)))
            .Where(entry => entry.Sequence.Direction != "client")
            .Where(entry => entry.Sequence.Headers.Any(header =>
                header.Equals("80 b2", StringComparison.OrdinalIgnoreCase)
                || header.Equals("80 bc", StringComparison.OrdinalIgnoreCase)))
            .ToArray();

        if (sequences.Length == 0)
        {
            return;
        }

        int bothCount = sequences.Count(entry =>
            entry.Sequence.Headers.Any(header => header.Equals("80 b2", StringComparison.OrdinalIgnoreCase))
            && entry.Sequence.Headers.Any(header => header.Equals("80 bc", StringComparison.OrdinalIgnoreCase)));

        builder.AppendLine("## Protocol 04 Server State Sequences");
        builder.AppendLine();
        builder.AppendLine("This groups top-level server protocol 04 packet header sequences that contain `80 b2` and/or `80 bc`. It preserves packet order so repeated state-bundle flows can be separated from isolated RPC hits.");
        builder.AppendLine();
        builder.AppendLine($"- State-related protocol 04 packets: {sequences.Length}");
        builder.AppendLine($"- Packets containing both `80 b2` and `80 bc`: {bothCount}");
        builder.AppendLine();
        builder.AppendLine("| Header sequence | Count | Contains `80 b2` | Contains `80 bc` | Sample |");
        builder.AppendLine("| --- | ---: | --- | --- | --- |");
        foreach (var group in sequences
            .GroupBy(entry => FormatSequence(entry.Sequence.Headers), StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(25))
        {
            Protocol04SequenceWithFile sample = group.First();
            bool hasB2 = sample.Sequence.Headers.Any(header => header.Equals("80 b2", StringComparison.OrdinalIgnoreCase));
            bool hasBc = sample.Sequence.Headers.Any(header => header.Equals("80 bc", StringComparison.OrdinalIgnoreCase));
            builder.AppendLine(
                $"| `{group.Key}` | {group.Count()} | {FormatBoolean(hasB2)} | {FormatBoolean(hasBc)} | `{sample.File}:{sample.Sequence.Line}` |");
        }

        builder.AppendLine();
        AppendProtocol04StateFieldLinks(builder, report);
    }

    private static void AppendProtocol04ServerPayloadShapeSummary(StringBuilder builder, PacketResearchReport report)
    {
        Protocol04ServerPayloadShapeWithFile[] payloads = report.PacketDumpFiles
            .SelectMany(file => (file.Protocol04ServerPayloadShapes ?? Array.Empty<Protocol04ServerPayloadShapeSample>())
                .Select(payload => new Protocol04ServerPayloadShapeWithFile(file.File, payload)))
            .ToArray();

        if (payloads.Length == 0)
        {
            return;
        }

        Dictionary<PacketLocation, string> sequencesByPacket = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04PacketSequences.Select(sequence => new
            {
                Packet = new PacketLocation(file.File, sequence.Line),
                Sequence = FormatSequence(sequence.Headers)
            }))
            .GroupBy(entry => entry.Packet)
            .ToDictionary(group => group.Key, group => group.First().Sequence);

        var groups = payloads
            .GroupBy(entry => new
            {
                entry.Payload.Header,
                LocalName = entry.Payload.LocalName ?? "(unknown)",
                entry.Payload.PayloadLength,
                entry.Payload.Field0,
                entry.Payload.Field1,
                entry.Payload.Field2
            })
            .Select(group => new
            {
                group.Key.Header,
                group.Key.LocalName,
                group.Key.PayloadLength,
                group.Key.Field0,
                group.Key.Field1,
                group.Key.Field2,
                Count = group.Count(),
                Texts = group
                    .SelectMany(entry => entry.Payload.Texts)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(text => text, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                CaptureScopes = group
                    .GroupBy(entry => FormatPacketCaptureScope(entry.File), StringComparer.OrdinalIgnoreCase)
                    .OrderByDescending(scope => scope.Count())
                    .ThenBy(scope => scope.Key, StringComparer.OrdinalIgnoreCase)
                    .Take(5)
                    .Select(scope => $"{scope.Key} ({scope.Count()})")
                    .ToArray(),
                Sequences = group
                    .Select(entry => sequencesByPacket.TryGetValue(new PacketLocation(entry.File, entry.Payload.Line), out string? sequence)
                        ? sequence
                        : "unsequenced")
                    .GroupBy(sequence => sequence, StringComparer.OrdinalIgnoreCase)
                    .OrderByDescending(sequence => sequence.Count())
                    .ThenBy(sequence => sequence.Key, StringComparer.OrdinalIgnoreCase)
                    .Take(5)
                    .Select(sequence => $"{sequence.Key} ({sequence.Count()})")
                    .ToArray(),
                Sample = group.First()
            })
            .OrderByDescending(group => group.Count)
            .ThenBy(group => group.Header, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.PayloadLength)
            .Take(40)
            .ToArray();

        builder.AppendLine("## Protocol 04 Additional Server Payload Shapes");
        builder.AppendLine();
        builder.AppendLine("This groups non-client protocol 04 payloads that do not yet have a specialized decoder. It is a triage table: leading words and printable strings are layout evidence, not final field semantics.");
        builder.AppendLine();
        builder.AppendLine("| Header | Local name | Payload bytes | Field 0 | Field 1 | Field 2 | Count | Text samples | Capture scopes | Top packet sequences | Sample | Prefix | Suffix |");
        builder.AppendLine("| --- | --- | ---: | --- | --- | --- | ---: | --- | --- | --- | --- | --- | --- |");
        foreach (var group in groups)
        {
            Protocol04ServerPayloadShapeWithFile sample = group.Sample;
            builder.AppendLine(
                $"| `{group.Header}` | {FormatTableText(group.LocalName)} | {group.PayloadLength} | `{group.Field0}` | `{group.Field1}` | `{group.Field2}` | {group.Count} | {FormatDistinct(group.Texts, 8)} | {FormatDistinct(group.CaptureScopes, 5)} | {FormatDistinct(group.Sequences, 5)} | `{sample.File}:{sample.Payload.Line}` | `{sample.Payload.PayloadPrefixHex}` | `{sample.Payload.PayloadSuffixHex}` |");
        }

        builder.AppendLine();
    }

