    {
        Protocol03SelectorFfRepeatListVendorBoundaryInterpretationSummary[] summaries = report.Protocol03SelectorFfRepeatListVendorBoundaryInterpretationSummaries
            .OrderBy(summary => summary.IsModeledFieldOverlap)
            .ThenByDescending(summary => summary.HeaderWindowCount)
            .ThenBy(summary => summary.TargetInterpretation, StringComparer.OrdinalIgnoreCase)
            .Take(20)
            .ToArray();
        if (summaries.Length == 0)
        {
            return;
        }

        builder.AppendLine("## Protocol 03 Selector ff Vendor Boundary Interpretation Rollup");
        builder.AppendLine();
        builder.AppendLine("This collapses vendor-only selector `ff` target rows by parser interpretation. Unresolved boundary candidates should drive body-length work first; modeled field overlaps are likely byte-window collisions unless future captures contradict the field model.");
        builder.AppendLine();
        builder.AppendLine("| Interpretation | Priority | Targets | Candidates | Windows | Target shapes | Headers | Regions | Payload offsets | Object offsets | Local offsets | Body spans | Body bytes | Position anchors | Entry 1 fields | Entry 2 effective fields | Post-marker fields | Top targets |");
        builder.AppendLine("| --- | --- | ---: | ---: | ---: | ---: | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |");
        foreach (Protocol03SelectorFfRepeatListVendorBoundaryInterpretationSummary summary in summaries)
        {
            builder.AppendLine(
                $"| {FormatTableText(summary.TargetInterpretation)} | {FormatTableText(summary.ParserPriority)} | {summary.TargetCount} | {summary.CandidateCount} | {summary.HeaderWindowCount} | {summary.ShapeCount} | {FormatCountDictionary(summary.Headers, 5)} | {FormatCountDictionary(summary.HeaderRegions, 5)} | {FormatCountDictionary(summary.PayloadOffsets, 5)} | {FormatCountDictionary(summary.ObjectOffsets, 5)} | {FormatCountDictionary(summary.TargetLocalOffsets, 5)} | {FormatCountDictionary(summary.TargetBodySpanBytes, 5)} | {FormatCountDictionary(summary.TargetBodyHexes, 5)} | {FormatCountDictionary(summary.PositionOffsets, 5)} | {FormatCountDictionary(summary.Entry1Fields, 5)} | {FormatCountDictionary(summary.Entry2EffectiveFields, 5)} | {FormatCountDictionary(summary.PostMarkerFields, 5)} | {FormatSelectorFfRepeatListVendorInterpretationTargets(summary.TopTargets, 5)} |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol03SelectorFfRepeatListVendorBoundaryTargetSummaries(StringBuilder builder, PacketResearchReport report)
    {
        Protocol03SelectorFfRepeatListVendorBoundaryTargetSummary[] summaries = report.Protocol03SelectorFfRepeatListVendorBoundaryTargetSummaries
            .OrderByDescending(summary => summary.CandidateCount)
            .ThenByDescending(summary => summary.HeaderWindowCount)
            .ThenByDescending(summary => summary.ShapeCount)
            .ThenBy(summary => summary.Name, StringComparer.OrdinalIgnoreCase)
            .ThenBy(summary => summary.HeaderRegion, StringComparer.OrdinalIgnoreCase)
            .ThenBy(summary => summary.HeaderPayloadOffset)
            .Take(40)
            .ToArray();
        if (summaries.Length == 0)
        {
            return;
        }

        builder.AppendLine("## Protocol 03 Selector ff Vendor Boundary Targets");
        builder.AppendLine();
        builder.AppendLine("This filters the selector `ff` header-window correlations to vendor-only byte windows and groups them by exact local payload/object offset. These rows are parser targets for separating packed-field collisions from repeat-entry and continuation-body boundaries; they are still byte-window evidence, not decoded nested RPCs.");
        builder.AppendLine();
        builder.AppendLine("| Header | Target | Region | Interpretation | Local offsets | Body spans | Body bytes | Position anchors | Candidates | Windows | Shapes | Top shapes | Window hexes | Continuation prefixes | Entry 1 fields | Entry 1 refs | Entry 2 effective fields | Entry 2 refs | Post-marker fields | Post-marker refs | First selectors | Sample |");
        builder.AppendLine("| --- | --- | --- | --- | --- | --- | --- | --- | ---: | ---: | ---: | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |");
        foreach (Protocol03SelectorFfRepeatListVendorBoundaryTargetSummary summary in summaries)
        {
            builder.AppendLine(
                $"| {FormatTableText(summary.Name)}<br>`{summary.EncodedHeader}` [{FormatSlashList(summary.Protocols, 4)} {FormatTableText(summary.Direction)}] | payload +{summary.HeaderPayloadOffset.ToString(CultureInfo.InvariantCulture)}<br>object +{summary.HeaderObjectOffset.ToString(CultureInfo.InvariantCulture)} | {FormatTableText(summary.HeaderRegion)} | {FormatCountDictionary(summary.TargetInterpretations, 5)} | {FormatCountDictionary(summary.TargetLocalOffsets, 5)} | {FormatCountDictionary(summary.TargetBodySpanBytes, 5)} | {FormatCountDictionary(summary.TargetBodyHexes, 5)} | {FormatCountDictionary(summary.PositionOffsets, 5)} | {summary.CandidateCount} | {summary.HeaderWindowCount} | {summary.ShapeCount} | {FormatSelectorFfRepeatListHeaderNameShapes(summary.TopShapes, 3)} | {FormatCountDictionary(summary.WindowHexes, 5)} | {FormatCountDictionary(summary.ContinuationPrefixes, 5)} | {FormatCountDictionary(summary.Entry1Fields, 5)} | {FormatCountDictionary(summary.Entry1ResourceReferences, 5)} | {FormatCountDictionary(summary.Entry2EffectiveFields, 5)} | {FormatCountDictionary(summary.Entry2EffectiveResourceReferences, 5)} | {FormatCountDictionary(summary.PostMarkerFields, 5)} | {FormatCountDictionary(summary.PostMarkerResourceReferences, 5)} | {FormatCountDictionary(summary.FirstSelectors, 6)} | `{summary.SampleFile}:{summary.SampleLine}` |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol03StaticObjectLeads(
        StringBuilder builder,
        PacketResearchReport report,
        IReadOnlyList<Protocol03SampleWithFile> samples)
    {
        Protocol03StaticObjectLeadWithFile[] leads = samples
            .SelectMany(entry => entry.Sample.StaticObjectLeads.Select(lead => new Protocol03StaticObjectLeadWithFile(entry.File, entry.Sample.Line, entry.Sample, lead)))
            .ToArray();
        if (leads.Length == 0)
        {
            return;
        }

        ILookup<uint, StaticObjectEntry> staticObjectsByMxoId = report.StaticObjectEntries.ToLookup(entry => entry.MxoId);
        ILookup<int, GameObjectEntry> gameObjectsById = report.GameObjectEntries.ToLookup(entry => entry.GoId);
        Dictionary<uint, int> vendorRowCounts = report.VendorInventoryEntries
            .GroupBy(entry => entry.VendorStaticId)
            .ToDictionary(group => group.Key, group => group.Count());

        builder.AppendLine("### Protocol 03 Static Object/Door Spawn Leads");
        builder.AppendLine();
        builder.AppendLine("This extracts the stable prefix from selector `3c`/`9e`/`9f`/`a0` static object variable blocks: a lead byte, little-endian static `mxoId`, instance byte, `cd ab` separator, protocol object-type byte `3`, a bounded quaternion window, and post-quaternion body bytes when full compact/headered packet samples are available. The first post-quaternion byte is followed by three little-endian doubles that land near matching static table coordinates; field semantics are still not claimed.");
        builder.AppendLine();
        builder.AppendLine($"Across {leads.Length} selector `3c`/`9e`/`9f`/`a0` tails, {leads.Select(entry => entry.Lead.ObjectId).Distinct().Count()} distinct static object ids appear.");
        builder.AppendLine();
        builder.AppendLine("| Selector | Static object id | Protocol object type | Records | Full payloads | Payload bytes | Static rows | Vendor rows | Static type symbols | Instance bytes | Separator | Quaternion samples | Post-quat bytes | Marker | Vector samples | Nearest static distance | Tail field 0 | Tail field 1 | Tail suffix | Tail samples | Sample |");
        builder.AppendLine("| --- | ---: | ---: | ---: | ---: | --- | ---: | ---: | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |");
        foreach (var group in leads
            .GroupBy(entry => new
            {
                entry.Lead.Selector,
                entry.Lead.ObjectId,
                entry.Lead.ObjectType
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.Selector, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.ObjectId))
        {
            Protocol03StaticObjectLeadWithFile sample = group.First();
            StaticObjectEntry[] staticRows = staticObjectsByMxoId[group.Key.ObjectId].ToArray();
            int fullPayloads = group.Count(entry => entry.Lead.PostQuaternionBytes > 0);
            builder.AppendLine(
                $"| `{group.Key.Selector}` | {group.Key.ObjectId} | {group.Key.ObjectType} | {group.Count()} | {fullPayloads} | {FormatDistinct(group.Select(entry => entry.Lead.PayloadBytes.ToString(CultureInfo.InvariantCulture)), 8)} | {staticRows.Length} | {vendorRowCounts.GetValueOrDefault(group.Key.ObjectId)} | {FormatStaticTypeSymbols(staticRows, gameObjectsById)} | {FormatDistinct(group.Select(entry => entry.Lead.InstanceByteHex), 8)} | {FormatDistinct(group.Select(entry => entry.Lead.SeparatorHex), 4)} | {FormatDistinct(group.Select(entry => FormatStaticObjectQuaternion(entry.Lead)), 4)} | {FormatDistinct(group.Select(entry => entry.Lead.PostQuaternionBytes > 0 ? entry.Lead.PostQuaternionBytes.ToString(CultureInfo.InvariantCulture) : null), 8)} | {FormatDistinct(group.Select(entry => string.IsNullOrWhiteSpace(entry.Lead.PostQuaternionMarkerHex) ? null : entry.Lead.PostQuaternionMarkerHex), 4)} | {FormatDistinct(group.Select(entry => FormatStaticObjectPostQuaternionVector(entry.Lead)), 4)} | {FormatDistinct(group.Select(entry => FormatStaticObjectNearestDistance(entry.Lead, staticRows)), 4)} | {FormatDistinct(group.Select(entry => FormatStaticObjectTailField(entry.Lead.PostQuaternionTailField0Hex, entry.Lead.PostQuaternionTailField0)), 4)} | {FormatDistinct(group.Select(entry => FormatStaticObjectTailField(entry.Lead.PostQuaternionTailField1Hex, entry.Lead.PostQuaternionTailField1)), 8)} | {FormatDistinct(group.Select(entry => string.IsNullOrWhiteSpace(entry.Lead.PostQuaternionTailSuffixHex) ? null : entry.Lead.PostQuaternionTailSuffixHex), 4)} | {FormatDistinct(group.Select(entry => string.IsNullOrWhiteSpace(entry.Lead.PostQuaternionTailHex) ? null : entry.Lead.PostQuaternionTailHex), 4)} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol03NestedMovementLeads(
        StringBuilder builder,
        IReadOnlyList<Protocol03SampleWithFile> samples)
    {
        Protocol03NestedMovementLeadWithFile[] leads = samples
            .SelectMany(entry => entry.Sample.NestedMovementLeads.Select(lead => new Protocol03NestedMovementLeadWithFile(entry.File, entry.Sample.Line, entry.Sample, lead)))
            .ToArray();
        if (leads.Length == 0)
        {
            return;
        }

        builder.AppendLine("### Protocol 03 Embedded Movement Leads");
        builder.AppendLine();
        builder.AppendLine("This scans unresolved selector payloads and bounded primary movement wrappers for embedded `00 <mode> <movement selector>` windows that carry plausible little-endian xyz positions. Rows from unresolved payloads are layout leads only; rows from primary wrappers use a known bounded prefix length.");
        builder.AppendLine();
        builder.AppendLine($"Across {leads.Length} embedded movement windows, {leads.Select(entry => entry.Lead.OuterSelector).Distinct(StringComparer.OrdinalIgnoreCase).Count()} outer selectors contain a plausible movement window.");
        builder.AppendLine("The first table groups the marker mode and inner movement selector; the second table lists the top grouped leads by record count.");
        builder.AppendLine();
        builder.AppendLine("| Marker mode | Inner selector | Records | Bounded primary wrappers | Unresolved payload leads | Object classifications | Outer selectors | Suffix samples | Sample |");
        builder.AppendLine("| --- | --- | ---: | ---: | ---: | --- | --- | --- | --- |");
        foreach (var group in leads
            .GroupBy(entry => new
            {
                entry.Lead.MarkerModeHex,
                entry.Lead.InnerSelector
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.MarkerModeHex, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.InnerSelector, StringComparer.OrdinalIgnoreCase))
        {
            Protocol03NestedMovementLeadWithFile sample = group.First();
            int boundedWrappers = group.Count(IsProtocol03BoundedPrimaryMovementWrapper);
            builder.AppendLine(
                $"| `{group.Key.MarkerModeHex}` | `{group.Key.InnerSelector}` | {group.Count()} | {boundedWrappers} | {group.Count() - boundedWrappers} | {FormatDistinct(group.Select(entry => entry.Sample.Classification), 5)} | {FormatDistinct(group.Select(entry => entry.Lead.OuterSelector), 10)} | {FormatDistinct(group.Select(entry => FormatEmptyHex(entry.Lead.SuffixHex)), 5)} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
        builder.AppendLine("The suffix table groups the first bytes after the embedded movement payload. Repeated non-empty suffixes are body-boundary leads only; they are not decoded tail lengths yet.");
        builder.AppendLine();
        builder.AppendLine("| Marker mode | Inner selector | Suffix prefix | Next bytes | Records | Bounded primary wrappers | Unresolved payload leads | Object classifications | Outer selectors | Payload bytes | Sample |");
        builder.AppendLine("| --- | --- | --- | --- | ---: | ---: | ---: | --- | --- | --- | --- |");
        foreach (var group in leads
            .GroupBy(entry => new
            {
                entry.Lead.MarkerModeHex,
                entry.Lead.InnerSelector,
                SuffixHex = FormatEmptyHex(entry.Lead.SuffixHex),
                PostSuffixHex = FormatEmptyHex(entry.Lead.PostSuffixHex)
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.MarkerModeHex, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.InnerSelector, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.SuffixHex, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.PostSuffixHex, StringComparer.OrdinalIgnoreCase)
            .Take(20))
        {
            Protocol03NestedMovementLeadWithFile sample = group.First();
            int boundedWrappers = group.Count(IsProtocol03BoundedPrimaryMovementWrapper);
            builder.AppendLine(
                $"| `{group.Key.MarkerModeHex}` | `{group.Key.InnerSelector}` | `{group.Key.SuffixHex}` | `{group.Key.PostSuffixHex}` | {group.Count()} | {boundedWrappers} | {group.Count() - boundedWrappers} | {FormatDistinct(group.Select(entry => entry.Sample.Classification), 5)} | {FormatDistinct(group.Select(entry => entry.Lead.OuterSelector), 10)} | {FormatDistinct(group.Select(entry => entry.Lead.PayloadBytes.ToString(CultureInfo.InvariantCulture)), 8)} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
        builder.AppendLine("| Outer selector | Object classification | Lead prefix | Marker offset | Marker mode | Inner selector | Records | Payload bytes | Position samples | Suffix samples | Sample |");
        builder.AppendLine("| --- | --- | --- | ---: | --- | --- | ---: | --- | --- | --- | --- |");
        var groups = leads
            .GroupBy(entry => new
            {
                entry.Lead.OuterSelector,
                entry.Sample.Classification,
                entry.Lead.LeadPrefixHex,
                entry.Lead.MarkerOffset,
                entry.Lead.MarkerModeHex,
                entry.Lead.InnerSelector
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.OuterSelector, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.MarkerOffset)
            .ThenBy(group => group.Key.MarkerModeHex, StringComparer.OrdinalIgnoreCase)
            .ThenBy(group => group.Key.InnerSelector, StringComparer.OrdinalIgnoreCase)
            .Take(25);
        foreach (var group in groups)
        {
            Protocol03NestedMovementLeadWithFile sample = group.First();
            builder.AppendLine(
                $"| `{group.Key.OuterSelector}` | {FormatTableText(group.Key.Classification)} | `{FormatEmptyHex(group.Key.LeadPrefixHex)}` | {group.Key.MarkerOffset} | `{group.Key.MarkerModeHex}` | `{group.Key.InnerSelector}` | {group.Count()} | {FormatDistinct(group.Select(entry => entry.Lead.PayloadBytes.ToString(CultureInfo.InvariantCulture)), 8)} | {FormatDistinct(group.Select(entry => FormatNestedMovementPosition(entry.Lead)), 4)} | {FormatDistinct(group.Select(entry => FormatEmptyHex(entry.Lead.SuffixHex)), 4)} | `{sample.File}:{sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static bool IsProtocol03BoundedPrimaryMovementWrapper(Protocol03NestedMovementLeadWithFile entry)
    {
        return entry.Sample.Segments.Any(segment =>
            segment.Classification.Equals("primary movement wrapper", StringComparison.Ordinal) &&
            segment.Selector.Equals(entry.Lead.OuterSelector, StringComparison.OrdinalIgnoreCase) &&
            segment.Offset + 1 == entry.Lead.Offset);
    }

