    private static void AppendProtocol03NpcBaseThreeByteZeroTailPreHeaderValues(
        StringBuilder builder,
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> boundaryLeads)
    {
        var zeroTailLeads = boundaryLeads
            .Select(candidate => new
            {
                Candidate = candidate,
                Value = TryReadThreeByteZeroTailPreHeaderValue(candidate.PostCreationObjectViewPreHeaderHex)
            })
            .Where(entry => entry.Value is not null)
            .ToArray();
        if (zeroTailLeads.Length == 0)
        {
            return;
        }

        int minValue = zeroTailLeads.Min(entry => entry.Value!.Value);
        int maxValue = zeroTailLeads.Max(entry => entry.Value!.Value);
        int exceptionCount = boundaryLeads.Count - zeroTailLeads.Length;
        string exceptionNoun = exceptionCount == 1 ? "lead" : "leads";
        string exceptionVerb = exceptionCount == 1 ? "uses" : "use";
        builder.AppendLine();
        builder.AppendLine($"The three-byte zero-tail pre-header values range from `{minValue:x2}` to `{maxValue:x2}`; {exceptionCount} boundary {exceptionNoun} {exceptionVerb} another pre-header shape.");
        builder.AppendLine();
        builder.AppendLine("| Pre-header value | Pre-header bytes | Records | Header classifications | Distinct header prefixes | Distinct names | Text samples | Sample |");
        builder.AppendLine("| --- | --- | ---: | --- | ---: | ---: | --- | --- |");
        foreach (var group in zeroTailLeads
            .GroupBy(entry => entry.Value!.Value)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(25))
        {
            Protocol03NamedProfileRecordCandidate sample = group.First().Candidate;
            int distinctHeaderPrefixes = group.Select(entry => entry.Candidate.PostCreationObjectViewHeaderHex).Distinct(StringComparer.OrdinalIgnoreCase).Count();
            int distinctNames = group.Select(entry => entry.Candidate.Text).Distinct(StringComparer.OrdinalIgnoreCase).Count();
            string preHeaderHex = $"{group.Key:x2} 00 00";
            builder.AppendLine(
                $"| `{group.Key:x2}` | `{preHeaderHex}` | {group.Count()} | {FormatDistinct(group.Select(entry => entry.Candidate.PostCreationObjectViewHeaderClassification), 8)} | {distinctHeaderPrefixes} | {distinctNames} | {FormatDistinct(group.Select(entry => entry.Candidate.Text), 8)} | `{sample.File}:{sample.Line}` |");
        }
    }

    private static void AppendProtocol03NpcBaseNonZeroTailPreHeaderExceptions(
        StringBuilder builder,
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> boundaryLeads)
    {
        Protocol03NamedProfileRecordCandidate[] exceptions = boundaryLeads
            .Where(candidate => !IsThreeByteZeroTailPreHeader(candidate.PostCreationObjectViewPreHeaderHex))
            .ToArray();
        if (exceptions.Length == 0)
        {
            return;
        }

        builder.AppendLine();
        builder.AppendLine("Non-zero-tail pre-header exceptions remain separate because they do not match the dominant `<value> 00 00` tail-field shape.");
        builder.AppendLine($"Exception classifications: {FormatCountSummary(exceptions.Select(candidate => candidate.PostCreationObjectViewHeaderClassification))}. Header offsets: {FormatCountSummary(exceptions.Select(candidate => candidate.PostCreationObjectViewHeaderOffset?.ToString(CultureInfo.InvariantCulture) ?? "-"))}.");
        builder.AppendLine();
        builder.AppendLine("| Header offset | Pre-header bytes | Records | Header classifications | Header prefixes | Distinct names | Text samples | Sample |");
        builder.AppendLine("| ---: | --- | ---: | --- | --- | ---: | --- | --- |");
        foreach (var group in exceptions
            .GroupBy(candidate => new
            {
                candidate.PostCreationObjectViewHeaderOffset,
                PreHeaderHex = FormatEmptyHex(candidate.PostCreationObjectViewPreHeaderHex)
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.PostCreationObjectViewHeaderOffset)
            .ThenBy(group => group.Key.PreHeaderHex, StringComparer.OrdinalIgnoreCase)
            .Take(25))
        {
            Protocol03NamedProfileRecordCandidate sample = group.First();
            int distinctNames = group.Select(candidate => candidate.Text).Distinct(StringComparer.OrdinalIgnoreCase).Count();
            builder.AppendLine(
                $"| {group.Key.PostCreationObjectViewHeaderOffset} | `{group.Key.PreHeaderHex}` | {group.Count()} | {FormatDistinct(group.Select(candidate => candidate.PostCreationObjectViewHeaderClassification), 8)} | {FormatDistinct(group.Select(candidate => candidate.PostCreationObjectViewHeaderHex), 6)} | {distinctNames} | {FormatDistinct(group.Select(candidate => candidate.Text), 8)} | `{sample.File}:{sample.Line}` |");
        }
    }

    private static void AppendProtocol03NpcBaseCreationEntityCorrelation(
        StringBuilder builder,
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates)
    {
        var allCorrelations = candidates
            .Where(candidate => candidate.EntityRows.Count > 0)
            .GroupBy(candidate => candidate.Text, StringComparer.OrdinalIgnoreCase)
            .Select(group =>
            {
                Protocol03NamedProfileRecordCandidate[] records = group.ToArray();
                WorldEntityEntry[] entityRows = records
                    .SelectMany(candidate => candidate.EntityRows)
                    .Distinct()
                    .ToArray();

                var level = CountEntityMatches(records, candidate => TryReadAttributeByte(candidate, 45), entityRows, row => row.Level);
                var health = CountHealthMatches(records, entityRows);
                var description = CountDescriptionMatches(records, entityRows);
                var position = SummarizeNearestPositions(records, entityRows);
                var npcRank = CountEntityMatches(records, candidate => TryReadAttributeByte(candidate, 36), entityRows, row => row.NpcRank);
                var debuffState = CountEntityMatches(records, candidate => TryReadAttributeByte(candidate, 50), entityRows, row => row.DebuffState);
                var currentState = CountCurrentStateMatches(records, entityRows);

                return new
                {
                    Text = group.Key,
                    Records = records,
                    EntityRows = entityRows,
                    Level = level,
                    Health = health,
                    Description = description,
                    Position = position,
                    NpcRank = npcRank,
                    DebuffState = debuffState,
                    CurrentState = currentState,
                    Sample = records[0]
                };
            })
            .Where(correlation => correlation.Level.Comparable > 0
                || correlation.Health.Comparable > 0
                || correlation.Description.Comparable > 0
                || correlation.Position.Comparable > 0
                || correlation.NpcRank.Comparable > 0
                || correlation.DebuffState.Comparable > 0
                || correlation.CurrentState.Comparable > 0)
            .ToArray();

        if (allCorrelations.Length == 0)
        {
            return;
        }

        var correlations = allCorrelations
            .OrderByDescending(correlation => correlation.Position.Within2500)
            .ThenByDescending(correlation => correlation.Position.Within5000)
            .ThenByDescending(correlation => correlation.Description.Matches)
            .ThenByDescending(correlation => correlation.Health.Matches)
            .ThenByDescending(correlation => correlation.Level.Matches)
            .ThenByDescending(correlation => correlation.Records.Length)
            .ThenBy(correlation => correlation.Text, StringComparer.OrdinalIgnoreCase)
            .Take(25)
            .ToArray();

        builder.AppendLine("### Protocol 03 NPC_BASE Creation Attribute Entity Correlation");
        builder.AppendLine();
        builder.AppendLine("This decodes selected Object599 creation attributes into typed values, then checks whether any tracked mob row with the same `CharacterName` has the same value. Matches are evidence for field semantics; misses may reflect duplicate names, different districts, or incomplete captures.");
        builder.AppendLine();
        PositionMatchSummary positionSummary = SumPositionSummaries(allCorrelations.Select(correlation => correlation.Position));
        builder.AppendLine($"Across {allCorrelations.Sum(correlation => correlation.Records.Length)} creation records with tracked same-name mob rows, matches are: level {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.Level)))}, health/max-health {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.Health)))}, description/RSI {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.Description)))}, NPC rank {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.NpcRank)))}, debuff state {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.DebuffState)))}, current state {FormatMatchCount(SumMatchCounts(allCorrelations.Select(correlation => correlation.CurrentState)))}, exact position {FormatPositionExact(positionSummary)}, nearest position within 1k {FormatPositionWithin(positionSummary, 1000)}, within 2.5k {FormatPositionWithin(positionSummary, 2500)}, and within 5k {FormatPositionWithin(positionSummary, 5000)}.");
        builder.AppendLine();
        builder.AppendLine("| Text | Records | Entity rows | Level | Health | Description/RSI | NPC rank | Debuff state | Current state | Exact position | Nearest <=2.5k | Median nearest | Decoded samples | Sample |");
        builder.AppendLine("| --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: | --- | --- |");
        foreach (var correlation in correlations)
        {
            builder.AppendLine(
                $"| {FormatTableText(correlation.Text)} | {correlation.Records.Length} | {correlation.EntityRows.Length} | {FormatMatchCount(correlation.Level)} | {FormatMatchCount(correlation.Health)} | {FormatMatchCount(correlation.Description)} | {FormatMatchCount(correlation.NpcRank)} | {FormatMatchCount(correlation.DebuffState)} | {FormatMatchCount(correlation.CurrentState)} | {FormatPositionExact(correlation.Position)} | {FormatPositionWithin(correlation.Position, 2500)} | {FormatDistance(correlation.Position.MedianNearest)} | {FormatDistinct(correlation.Records.Select(FormatNpcBaseDecodedSummary), 3)} | `{correlation.Sample.File}:{correlation.Sample.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendProtocol03NpcBaseCreationSymbolLeads(
        StringBuilder builder,
        PacketResearchReport report,
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates)
    {
        ILookup<int, GameObjectEntry> gameObjectsById = report.GameObjectEntries
            .ToLookup(entry => entry.GoId);
        Dictionary<uint, ItemCommandEntry> itemsById = BuildItemCommandDictionary(report.ItemCommandEntries);
        Dictionary<string, FxDefinition> fxByHex = BuildFxDictionary(report.FxDefinitions);

        var equipmentGroups = candidates
            .Select(candidate => new
            {
                Candidate = candidate,
                Hex = TryGetAttributeHex(candidate, 56),
                RawId = TryReadAttributeUInt32(candidate, 56)
            })
            .Where(row => row.Hex is not null && row.RawId is not null)
            .GroupBy(row => new
            {
                Hex = row.Hex!,
                Id = unchecked((int)row.RawId!.Value)
            })
            .Select(group => new
            {
                group.Key.Hex,
                group.Key.Id,
                Count = group.Count(),
                Texts = group.Select(row => row.Candidate.Text),
                Sample = group.First().Candidate,
                Symbols = gameObjectsById[group.Key.Id]
                    .Select(entry => entry.CodeName)
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .ToArray(),
                ItemCommands = itemsById.TryGetValue(unchecked((uint)group.Key.Id), out ItemCommandEntry? item)
                    ? new[] { FormatItemReference(item.ItemId, itemsById) }
                    : Array.Empty<string>()
            })
            .OrderByDescending(group => group.Count)
            .ThenBy(group => group.Id)
            .Take(25)
            .ToArray();

        var effectGroups = candidates
            .Select(candidate =>
            {
                string? hex = TryGetAttributeHex(candidate, 22);
                string? normalizedHex = NormalizeHex(hex);
                fxByHex.TryGetValue(normalizedHex ?? string.Empty, out FxDefinition? fx);
                return new
                {
                    Candidate = candidate,
                    Hex = hex,
                    NormalizedHex = normalizedHex,
                    Fx = fx,
                    Counter = TryGetAttributeHex(candidate, 7)
                };
            })
            .Where(row => row.Hex is not null && row.NormalizedHex is not null)
            .GroupBy(row => row.NormalizedHex!, StringComparer.OrdinalIgnoreCase)
            .Select(group =>
            {
                var sample = group.First();
                return new
                {
                    Hex = sample.Hex!,
                    Count = group.Count(),
                    FxNames = group
                        .Select(row => row.Fx?.Name)
                        .Where(value => !string.IsNullOrWhiteSpace(value))
                        .Select(value => value!)
                        .Distinct(StringComparer.OrdinalIgnoreCase)
                        .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                        .ToArray(),
                    Counters = group.Select(row => row.Counter),
                    Texts = group.Select(row => row.Candidate.Text),
                    Sample = sample.Candidate
                };
            })
            .OrderByDescending(group => group.Count)
            .ThenBy(group => group.Hex, StringComparer.OrdinalIgnoreCase)
            .Take(25)
            .ToArray();

        if (equipmentGroups.Length == 0 && effectGroups.Length == 0)
        {
            return;
        }

        builder.AppendLine("### Protocol 03 NPC_BASE Equipment and Effect Symbol Leads");
        builder.AppendLine();
        builder.AppendLine("This resolves Object599 `EquippedItemID` through imported `gameobjects.csv` rows and the MxOEmu `&gib` command list, then resolves `EffectID` through imported FX definitions. Any unmatched values remain raw packet leads for targeted capture work.");
        builder.AppendLine();

        if (equipmentGroups.Length > 0)
        {
            builder.AppendLine("| EquippedItemID | GameObject id | GameObject symbols | Inventory command item | Records | Text samples | Sample |");
            builder.AppendLine("| --- | ---: | --- | --- | ---: | --- | --- |");
            foreach (var group in equipmentGroups)
            {
                builder.AppendLine(
                    $"| `{group.Hex}` | {group.Id} | {FormatCandidateList(group.Symbols.Select(FormatTableText).ToArray())} | {FormatCandidateList(group.ItemCommands)} | {group.Count} | {FormatDistinct(group.Texts, 8)} | `{group.Sample.File}:{group.Sample.Line}` |");
            }

            builder.AppendLine();
        }

        if (effectGroups.Length > 0)
        {
            builder.AppendLine("| EffectID | FX name | Effect counters | Records | Text samples | Sample |");
            builder.AppendLine("| --- | --- | --- | ---: | --- | --- |");
            foreach (var group in effectGroups)
            {
                builder.AppendLine(
                    $"| `{group.Hex}` | {FormatCandidateList(group.FxNames.Select(FormatTableText).ToArray())} | {FormatDistinct(group.Counters, 8)} | {group.Count} | {FormatDistinct(group.Texts, 8)} | `{group.Sample.File}:{group.Sample.Line}` |");
            }

            builder.AppendLine();
        }
    }

    private static void AppendProtocol03NpcBaseCreationAttributePresence(
        StringBuilder builder,
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates)
    {
        var attributes = candidates
            .SelectMany(candidate => candidate.CreationAttributes.Select(attribute => new
            {
                Candidate = candidate,
                Attribute = attribute
            }))
            .ToArray();
        if (attributes.Length == 0)
        {
            return;
        }

        builder.AppendLine("### Protocol 03 NPC_BASE Creation Attribute Presence");
        builder.AppendLine();
        builder.AppendLine("This walks Object599 creation masks using local fixed attribute sizes, then groups every decoded attribute by creation index and value. Values are still raw bytes; names come from the local Object599 definition.");
        builder.AppendLine();
        builder.AppendLine("| Index | Attribute | Size | Records | Distinct values | Value samples | Text samples | Sample |");
        builder.AppendLine("| ---: | --- | ---: | ---: | ---: | --- | --- | --- |");
        foreach (var group in attributes
            .GroupBy(entry => new
            {
                entry.Attribute.Index,
                entry.Attribute.Name,
                entry.Attribute.Size
            })
            .OrderBy(group => group.Key.Index))
        {
            var sample = group.First();
            int distinctValues = group.Select(entry => entry.Attribute.ValueHex).Distinct(StringComparer.OrdinalIgnoreCase).Count();
            builder.AppendLine(
                $"| {group.Key.Index} | {group.Key.Name} | {group.Key.Size} | {group.Count()} | {distinctValues} | {FormatDistinct(group.Select(entry => entry.Attribute.ValueHex), 5)} | {FormatDistinct(group.Select(entry => entry.Candidate.Text), 8)} | `{sample.Candidate.File}:{sample.Candidate.Line}` |");
        }

        builder.AppendLine();
    }

    private static void AppendHardcodedProtocol03Examples(StringBuilder builder, PacketResearchReport report)
    {
        Protocol03HardcodedExample[] examples = report.HardcodedProtocol03Examples
            .OrderBy(example => example.Source)
            .ThenBy(example => example.File, StringComparer.OrdinalIgnoreCase)
            .ThenBy(example => example.Line)
            .ToArray();

        if (examples.Length == 0)
        {
            return;
        }

        builder.AppendLine("## Hardcoded Protocol 03 Examples");
        builder.AppendLine();
        builder.AppendLine("This mines local and external hardcoded object-message constants, including Rajko/TasteeWheat `HexGenericMsg` examples and local `hexStringToBytes` object messages. These examples are provenance hints for protocol 03 layouts, not proof of live-client captures.");
        builder.AppendLine();
        builder.AppendLine("| Source | Location | Payload bytes | Object messages | Fully segmented | Top classification | Prefix |");
        builder.AppendLine("| --- | --- | ---: | ---: | ---: | --- | --- |");
        foreach (Protocol03HardcodedExample example in examples.Take(40))
        {
            var topClassification = example.ObjectViews
                .GroupBy(sample => sample.Classification)
                .OrderByDescending(group => group.Count())
                .ThenBy(group => group.Key)
                .First();
            builder.AppendLine(
                $"| {example.Source} | `{FormatSourceLocation(example.File, example.Line)}` | {example.PayloadLength} | {example.ObjectViews.Count} | {example.ObjectViews.Count(sample => sample.Complete)} | {topClassification.Key} ({topClassification.Count()}) | `{example.PrefixHex}` |");
        }

        builder.AppendLine();
    }

    private static void AppendPlayerAttributePayloadSummary(StringBuilder builder, PacketResearchReport report)
    {
        var payloads = report.PacketDumpFiles
            .SelectMany(file => file.PlayerAttributePayloads.Select(payload => new PlayerAttributePayloadWithFile(file.File, payload)))
            .ToArray();

        HardcodedCommandExample[] hardcoded = report.HardcodedCommands
            .Where(command => command.RawHeader.Equals("80 b2", StringComparison.OrdinalIgnoreCase))
            .OrderBy(command => command.Source)
            .ThenBy(command => command.File, StringComparer.OrdinalIgnoreCase)
            .ThenBy(command => command.Line)
            .ToArray();

        if (payloads.Length == 0 && hardcoded.Length == 0)
        {
            return;
        }

        builder.AppendLine("## SERVER_PLAYER_ATTRIBUTE / SERVER_ABILITY_LOAD Payload Groups");
        builder.AppendLine();
        builder.AppendLine("The local protocol map aliases `80 b2` as both `SERVER_PLAYER_ATTRIBUTE` and `SERVER_ABILITY_LOAD`, so this section treats it as an ambiguous server attribute/ability-load family until paired client actions prove the semantics.");
        builder.AppendLine();

        if (payloads.Length > 0)
        {
            builder.AppendLine("| Payload bytes | Field 0 | Field 1 | Field 2 | Count | Sample | Sample payload |");
            builder.AppendLine("| ---: | --- | --- | --- | ---: | --- | --- |");
            foreach (var group in payloads
                .GroupBy(entry => new
                {
                    entry.Payload.PayloadLength,
                    entry.Payload.Field0,
                    entry.Payload.Field1,
                    entry.Payload.Field2
                })
                .OrderByDescending(group => group.Count())
                .ThenBy(group => group.Key.PayloadLength)
                .ThenBy(group => group.Key.Field0)
                .ThenBy(group => group.Key.Field1)
                .Take(25))
            {
                PlayerAttributePayloadWithFile sample = group.First();
                builder.AppendLine(
                    $"| {group.Key.PayloadLength} | `{group.Key.Field0}` | `{group.Key.Field1}` | `{group.Key.Field2}` | {group.Count()} | `{sample.File}:{sample.Payload.Line}` | `{sample.Payload.PayloadHex}` |");
            }

            builder.AppendLine();
        }

        AppendPlayerAttributeHardcodedExamples(builder, payloads, hardcoded);
        AppendPlayerAttributeIndexCandidates(builder, report, payloads);
    }

    private static void AppendAbilityUnloadPayloadSummary(StringBuilder builder, PacketResearchReport report)
    {
        var payloads = report.PacketDumpFiles
            .SelectMany(file => (file.AbilityUnloadPayloads ?? Array.Empty<AbilityUnloadPayloadSample>())
                .Select(payload => new AbilityUnloadPayloadWithFile(file.File, payload)))
            .ToArray();

        if (payloads.Length == 0)
        {
            return;
        }

        Dictionary<PacketLocation, PayloadWithFile[]> bcByPacket = report.PacketDumpFiles
            .SelectMany(file => file.ManageBonusPayloads.Select(payload => new PayloadWithFile(file.File, payload)))
            .GroupBy(entry => new PacketLocation(entry.File, entry.Payload.Line))
            .ToDictionary(group => group.Key, group => group.ToArray());
        Dictionary<PacketLocation, string> sequencesByPacket = report.PacketDumpFiles
            .SelectMany(file => file.Protocol04PacketSequences.Select(sequence => new
            {
                Packet = new PacketLocation(file.File, sequence.Line),
                Sequence = FormatSequence(sequence.Headers)
            }))
            .GroupBy(entry => entry.Packet)
            .ToDictionary(group => group.Key, group => group.First().Sequence);

        var groups = payloads
            .GroupBy(entry => new
            {
                entry.Payload.PayloadLength,
                entry.Payload.Field0
            })
            .Select(group => new
            {
                group.Key.PayloadLength,
                group.Key.Field0,
                Count = group.Count(),
                SamePacketManageBonusField1Matches = group.Sum(entry =>
                    bcByPacket.TryGetValue(new PacketLocation(entry.File, entry.Payload.Line), out PayloadWithFile[]? bcEntries)
                        ? bcEntries.Count(bc => bc.Payload.Field1.Equals(entry.Payload.Field0, StringComparison.OrdinalIgnoreCase))
                        : 0),
                CaptureScopes = group
                    .GroupBy(entry => FormatPacketCaptureScope(entry.File), StringComparer.OrdinalIgnoreCase)
                    .OrderByDescending(scope => scope.Count())
                    .ThenBy(scope => scope.Key, StringComparer.OrdinalIgnoreCase)
                    .Take(5)
                    .Select(scope => $"{scope.Key} ({scope.Count()})")
                    .ToArray(),
                Sequences = group
                    .Select(entry => sequencesByPacket.TryGetValue(new PacketLocation(entry.File, entry.Payload.Line), out string? sequence)
                        ? sequence
                        : "unsequenced")
                    .GroupBy(sequence => sequence, StringComparer.OrdinalIgnoreCase)
                    .OrderByDescending(sequence => sequence.Count())
                    .ThenBy(sequence => sequence.Key, StringComparer.OrdinalIgnoreCase)
                    .Take(5)
                    .Select(sequence => $"{sequence.Key} ({sequence.Count()})")
                    .ToArray(),
                Sample = group.First()
            })
            .OrderByDescending(group => group.Count)
            .ThenBy(group => group.PayloadLength)
            .ThenBy(group => group.Field0, StringComparer.OrdinalIgnoreCase)
            .Take(25)
            .ToArray();

        builder.AppendLine("## SERVER_ABILITY_UNLOAD Payload Groups");
        builder.AppendLine();
        builder.AppendLine("This groups top-level protocol 04 `80 b3` payloads. The local protocol map names this packet `SERVER_ABILITY_UNLOAD`; same-packet `80 bc` field-1 matches are treated as layout links, not final ability semantics.");
        builder.AppendLine();
        builder.AppendLine("| Payload bytes | Field 0 | Count | Same-packet `80 bc` field 1 matches | Capture scopes | Top packet sequences | Sample | Sample payload |");
        builder.AppendLine("| ---: | --- | ---: | ---: | --- | --- | --- | --- |");
        foreach (var group in groups)
        {
            AbilityUnloadPayloadWithFile sample = group.Sample;
            builder.AppendLine(
                $"| {group.PayloadLength} | `{group.Field0}` | {group.Count} | {group.SamePacketManageBonusField1Matches} | {FormatDistinct(group.CaptureScopes, 5)} | {FormatDistinct(group.Sequences, 5)} | `{sample.File}:{sample.Payload.Line}` | `{sample.Payload.PayloadHex}` |");
        }

        builder.AppendLine();
    }

