            .Select(sample => $"`{sample.File.File}:{sample.Flow.Line} -> {sample.Position} {sample.Packet.Line}`")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(4)
            .ToArray();

        return formatted.Length == 0 ? "-" : string.Join("<br>", formatted);
