    private static string FormatProtocol03WindowContexts(IEnumerable<FileWindowLocations> samples)
    {
        string[] contexts = samples
            .SelectMany(sample => EnumerateProtocol03WindowContexts(sample.File, sample.Window))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(4)
            .ToArray();

        return contexts.Length == 0 ? "-" : string.Join("<br>", contexts);
    }

    private static IEnumerable<string> EnumerateProtocol03WindowContexts(PacketDumpFileSummary file, KnownHeaderWindowSummary window)
    {
        if (window.SampleLocations is not null && window.SampleLocations.Count > 0)
        {
            foreach (KnownHeaderWindowLocation location in window.SampleLocations)
            {
                Protocol03ObjectViewSample[] samePacketViews = file.Protocol03ObjectViews
                    .Where(view => view.Line == location.PacketStartLine)
                    .ToArray();
                Protocol03ObjectViewSample[] containingViews = samePacketViews
                    .Where(view => ContainsPacketOffset(view, location.PacketOffset))
                    .ToArray();

                foreach (Protocol03ObjectViewSample view in containingViews.Length == 0 ? samePacketViews : containingViews)
                {
                    yield return FormatProtocol03WindowContext(view, location.PacketOffset);
                }
            }

            yield break;
        }

        foreach (int line in window.SamplePacketStartLines)
        {
            foreach (Protocol03ObjectViewSample view in file.Protocol03ObjectViews.Where(view => view.Line == line))
            {
                yield return FormatProtocol03WindowContext(view, null);
            }
        }
    }

    private static bool ContainsPacketOffset(Protocol03ObjectViewSample view, int packetOffset)
    {
        if (view.PacketOffset < 0)
        {
            return false;
        }

        int relativeOffset = packetOffset - view.PacketOffset;
        return relativeOffset >= 0 && relativeOffset < EstimateProtocol03ObjectViewBytes(view);
    }

    private static int EstimateProtocol03ObjectViewBytes(Protocol03ObjectViewSample view)
    {
        int segmentEnd = view.Segments.Count == 0
            ? 4
            : view.Segments.Max(segment => segment.Offset + 1 + Math.Max(0, segment.PayloadBytes));
        return Math.Max(4, segmentEnd);
    }

    private static string FormatProtocol03WindowContext(Protocol03ObjectViewSample view, int? packetOffset)
    {
        Protocol03ObjectUpdateSegment? containingSegment = packetOffset is null
            ? null
            : FindContainingSegment(view, packetOffset.Value);
        if (containingSegment is not null)
        {
            int relativeOffset = packetOffset!.Value - view.PacketOffset;
            return FormatTableText(
                $"count {view.UpdateCount}, first {view.FirstSelector}, {view.Classification}; segment {containingSegment.Selector} {containingSegment.Classification} at +{relativeOffset}");
        }

        string segmentSummary = string.Join(" -> ", view.Segments
            .Take(3)
            .Select(segment => $"{segment.Selector} {segment.Classification}"));
        return FormatTableText($"count {view.UpdateCount}, first {view.FirstSelector}, {view.Classification}; segments {segmentSummary}");
    }

    private static Protocol03ObjectUpdateSegment? FindContainingSegment(Protocol03ObjectViewSample view, int packetOffset)
    {
        if (view.PacketOffset < 0)
        {
            return null;
        }

        int relativeOffset = packetOffset - view.PacketOffset;
        return view.Segments.FirstOrDefault(segment =>
        {
            int payloadStart = segment.Offset + 1;
            int payloadEnd = payloadStart + Math.Max(0, segment.PayloadBytes);
            return relativeOffset >= payloadStart && relativeOffset < payloadEnd;
        });
    }

    private static string[] AttributeCandidates(
        IReadOnlyList<AttributeDefinition> attributes,
        int fieldValue,
        bool creationIndex)
    {
        return attributes
            .Where(attribute => creationIndex ? attribute.CreationIndex == fieldValue : attribute.UpdateIndex == fieldValue)
            .GroupBy(attribute => attribute.AttributeName, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(8)
            .Select(group => $"{group.Key} ({group.Count()})")
            .ToArray();
    }

    private static string FormatCandidateList(IReadOnlyList<string> candidates)
    {
        return candidates.Count == 0
            ? "-"
            : string.Join("<br>", candidates);
    }

    private static string FormatItemReferences(IEnumerable<uint> itemIds, IReadOnlyDictionary<uint, ItemCommandEntry> itemsById)
    {
        string[] references = itemIds
            .Select(id => FormatItemReference(id, itemsById))
            .ToArray();
        return FormatCandidateList(references);
    }

    private static string FormatItemReference(uint itemId, IReadOnlyDictionary<uint, ItemCommandEntry> itemsById)
    {
        if (!itemsById.TryGetValue(itemId, out ItemCommandEntry? item))
        {
            return itemId.ToString(CultureInfo.InvariantCulture);
        }

        string reference = $"{itemId.ToString(CultureInfo.InvariantCulture)} {FormatTableText(item.Symbol)}";
        return string.IsNullOrWhiteSpace(item.DisplayName)
            ? reference
            : $"{reference}: {FormatTableText(item.DisplayName)}";
    }

    private static string FormatAbilityReference(uint abilityId, IReadOnlyDictionary<uint, AbilityDefinition> abilitiesById)
    {
        if (!abilitiesById.TryGetValue(abilityId, out AbilityDefinition? ability))
        {
            return abilityId.ToString(CultureInfo.InvariantCulture);
        }

        string reference = $"{abilityId.ToString(CultureInfo.InvariantCulture)} {FormatTableText(ability.CodeName)}";
        return string.IsNullOrWhiteSpace(ability.DisplayName)
            ? reference
            : $"{reference}: {FormatTableText(ability.DisplayName)}";
    }

    private static string FormatTableText(string value)
    {
        return value
            .Replace("|", "\\|", StringComparison.Ordinal)
            .Replace("`", "'", StringComparison.Ordinal);
    }

    private static string FormatDistinct(IEnumerable<string?> values, int take = 5)
    {
        string[] distinct = values
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value!.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (distinct.Length == 0)
        {
            return "-";
        }

        string formatted = string.Join("<br>", distinct.Take(take).Select(FormatTableText));
        return distinct.Length > take
            ? $"{formatted}<br>+{distinct.Length - take} more"
            : formatted;
    }

    private static string FormatResourceReferences(IEnumerable<string?> values, int take = 8)
    {
        string[] distinct = values
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .Select(value => value!.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (distinct.Length == 0)
        {
            return "-";
        }

        string formatted = string.Join("<br>", distinct.Take(take).Select(FormatTableText));
        return distinct.Length > take
            ? $"{formatted}<br>+{distinct.Length - take} more"
            : formatted;
    }

    private static string FormatCountDictionary(IReadOnlyDictionary<string, int> values, int take = 5)
    {
        if (values.Count == 0)
        {
            return "-";
        }

        var ordered = values
            .OrderByDescending(entry => entry.Value)
            .ThenBy(entry => entry.Key, StringComparer.OrdinalIgnoreCase)
            .ToArray();
        string formatted = string.Join("<br>", ordered
            .Take(take)
            .Select(entry => $"{FormatTableText(entry.Key)} ({entry.Value.ToString(CultureInfo.InvariantCulture)})"));
        return ordered.Length > take
            ? $"{formatted}<br>+{ordered.Length - take} more"
            : formatted;
    }

    private static string FormatSelectorFfRepeatListShapePositions(
        IReadOnlyList<Protocol03SelectorFfRepeatListShapePositionSample> samples,
        int take = 4)
    {
        if (samples.Count == 0)
        {
            return "-";
        }

        string[] positions = samples
            .Select(sample => $"{FormatCoordinate(sample.X)},{FormatCoordinate(sample.Y)},{FormatCoordinate(sample.Z)}")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        string formatted = string.Join("<br>", positions.Take(take).Select(FormatTableText));
        return positions.Length > take
            ? $"{formatted}<br>+{positions.Length - take} more"
            : formatted;
    }

    private static string FormatSelectorFfRepeatListDecodedRowEntries(Protocol03SelectorFfRepeatListDecodedRow row)
    {
        string entry1 = FormatProtocol03RepeatRecordFieldShape(row.Entry1ZeroRun, row.Entry1FieldOffset, row.Entry1FieldHex);
        string entry2 = FormatProtocol03RepeatRecordFieldShape(row.Entry2ZeroRun, row.Entry2FieldOffset, row.Entry2FieldHex);
        string entry2Secondary = row.Entry2SecondaryFieldOffset is null
            ? "-"
            : $"+{row.Entry2SecondaryFieldOffset.Value.ToString(CultureInfo.InvariantCulture)} {FormatProtocol03NullableU16Field(row.Entry2SecondaryFieldHex)}";
        string entry2Effective = row.Entry2EffectiveFieldOffset is null
            ? "-"
            : $"+{row.Entry2EffectiveFieldOffset.Value.ToString(CultureInfo.InvariantCulture)} {FormatProtocol03NullableU16Field(row.Entry2EffectiveFieldHex)}";

        return string.Join("<br>", new[]
        {
            $"stride {row.RepeatStride.ToString(CultureInfo.InvariantCulture)}, records {row.RepeatRecordCount.ToString(CultureInfo.InvariantCulture)}",
            $"entry1 {entry1} ({FormatTableText(row.Entry1FieldLayoutKind)})",
            $"entry2 primary {entry2} ({FormatTableText(row.Entry2FieldLayoutKind)})",
            $"entry2 secondary {entry2Secondary}",
            $"entry2 effective {entry2Effective} ({FormatTableText(row.Entry2EffectiveFieldSource)})"
        });
    }

    private static string FormatSelectorFfRepeatListDecodedRowContinuation(Protocol03SelectorFfRepeatListDecodedRow row)
    {
        return string.Join("<br>", new[]
        {
            $"list +{row.ContinuationOffset.ToString(CultureInfo.InvariantCulture)}, bytes {row.ContinuationBytes.ToString(CultureInfo.InvariantCulture)}",
            $"prefix `{FormatEmptyHex(row.ContinuationPrefixHex)}`",
            $"pre-marker `{FormatEmptyHex(row.ContinuationPrefixBeforeMarkerHex)}`",
            $"marker +{row.ContinuationMarkerOffset.ToString(CultureInfo.InvariantCulture)} `{FormatEmptyHex(row.ContinuationMarkerHex)}`",
            FormatTableText(row.ContinuationMarkerRole)
        });
    }

    private static string FormatSelectorFfRepeatListDecodedRowContext(Protocol03SelectorFfRepeatListDecodedRow row)
    {
        string direction = string.IsNullOrWhiteSpace(row.Direction)
            ? "-"
            : FormatTableText(row.Direction);
        return string.Join("<br>", new[]
        {
            $"{direction}; view {row.ViewId.ToString(CultureInfo.InvariantCulture)}, count {row.UpdateCount.ToString(CultureInfo.InvariantCulture)}, first `{row.FirstSelector}`",
            FormatTableText(row.SegmentClassification),
            $"payload bytes {row.PayloadBytes.ToString(CultureInfo.InvariantCulture)}, selector +{row.SelectorOffset.ToString(CultureInfo.InvariantCulture)}",
            $"position +{row.PositionOffset.ToString(CultureInfo.InvariantCulture)} {FormatCoordinate(row.X)},{FormatCoordinate(row.Y)},{FormatCoordinate(row.Z)}"
        });
    }

    private static string FormatSelectorFfRepeatListHeaderWindows(
        IReadOnlyList<Protocol03SelectorFfRepeatListHeaderWindowSummary> summaries,
        int take)
    {
        if (summaries.Count == 0)
        {
            return "-";
        }

        string formatted = string.Join("<br>", summaries
            .Take(take)
            .Select(summary =>
            {
                string protocols = FormatSlashList(summary.Protocols, 4);
                return $"payload +{summary.PayloadOffset.ToString(CultureInfo.InvariantCulture)}/object {FormatCountDictionary(summary.ObjectOffsets, 3)} {FormatTableText(summary.Name)} [{protocols} {FormatTableText(summary.Direction)}] `{summary.EncodedHeader}` ({summary.Count.ToString(CultureInfo.InvariantCulture)}); windows {FormatCountDictionary(summary.WindowHexes, 2)}";
            }));
        return summaries.Count > take
            ? $"{formatted}<br>+{summaries.Count - take} more"
            : formatted;
    }

    private static string FormatSelectorFfRepeatListVendorInterpretationTargets(
        IReadOnlyList<Protocol03SelectorFfRepeatListVendorBoundaryInterpretationTargetSummary> targets,
        int take)
    {
        if (targets.Count == 0)
        {
            return "-";
        }

        string formatted = string.Join("<br>", targets
            .Take(take)
            .Select(target =>
            {
                string protocols = FormatSlashList(target.Protocols, 4);
                return $"{FormatTableText(target.Name)} [{protocols} {FormatTableText(target.Direction)}] `{target.EncodedHeader}` {FormatTableText(target.HeaderRegion)} payload +{target.HeaderPayloadOffset.ToString(CultureInfo.InvariantCulture)}/object +{target.HeaderObjectOffset.ToString(CultureInfo.InvariantCulture)} ({target.HeaderWindowCount.ToString(CultureInfo.InvariantCulture)}); local {FormatCountDictionary(target.TargetLocalOffsets, 2)}; span {FormatCountDictionary(target.TargetBodySpanBytes, 2)}; body {FormatCountDictionary(target.TargetBodyHexes, 2)}; position {FormatCountDictionary(target.PositionOffsets, 2)}; entry2 {FormatCountDictionary(target.Entry2EffectiveFields, 2)}; post {FormatCountDictionary(target.PostMarkerFields, 2)}";
            }));
        return targets.Count > take
            ? $"{formatted}<br>+{targets.Count - take} more"
            : formatted;
    }

    private static string FormatSelectorFfRepeatListHeaderNameShapes(
        IReadOnlyList<Protocol03SelectorFfRepeatListHeaderNameShapeSummary> summaries,
        int take)
    {
        if (summaries.Count == 0)
        {
            return "-";
        }

        string formatted = string.Join("<br>", summaries
            .Take(take)
            .Select(summary =>
                $"{FormatProtocol03RepeatRecordFieldShape(summary.Entry1ZeroRun, summary.Entry1FieldOffset, summary.Entry1FieldHex)} -> {FormatProtocol03NullableU16Field(summary.Entry2EffectiveFieldHex)} -> `{FormatEmptyHex(summary.ContinuationPrefixHex)}` -> {FormatProtocol03RepeatRecordFieldShape(summary.PostMarkerZeroRun, summary.PostMarkerFirstFieldOffset, summary.PostMarkerFirstFieldHex)} ({summary.CandidateCount.ToString(CultureInfo.InvariantCulture)} candidates, {summary.HeaderWindowCount.ToString(CultureInfo.InvariantCulture)} windows)"));
        return summaries.Count > take
            ? $"{formatted}<br>+{summaries.Count - take} more"
            : formatted;
    }

    private static string FormatSelectorFfRepeatListHeaderSampleHeader(Protocol03SelectorFfRepeatListHeaderSample sample)
    {
        string protocols = FormatSlashList(sample.Protocols, 4);
        return $"{FormatTableText(sample.Name)}<br>`{sample.EncodedHeader}` [{protocols} {FormatTableText(sample.Direction)}]";
    }

    private static string FormatSelectorFfRepeatListHeaderSampleSource(Protocol03SelectorFfRepeatListHeaderSample sample)
    {
        string packetDirection = string.IsNullOrWhiteSpace(sample.PacketDirection)
            ? "-"
            : FormatTableText(sample.PacketDirection);
        return $"{FormatTableText(sample.File)}:{sample.Line.ToString(CultureInfo.InvariantCulture)}<br>{packetDirection}; view {sample.ViewId.ToString(CultureInfo.InvariantCulture)}, count {sample.UpdateCount.ToString(CultureInfo.InvariantCulture)}, first `{sample.FirstSelector}`<br>{FormatTableText(sample.SegmentClassification)}";
    }

    private static string FormatSelectorFfRepeatListHeaderSampleOffsets(Protocol03SelectorFfRepeatListHeaderSample sample)
    {
        return $"{FormatTableText(sample.HeaderRegion)}<br>{FormatTableText(sample.HeaderInterpretation)}<br>{FormatTableText(sample.TargetLocalOffset)}<br>payload +{sample.HeaderPayloadOffset.ToString(CultureInfo.InvariantCulture)}; object +{sample.HeaderObjectOffset.ToString(CultureInfo.InvariantCulture)}; selector +{sample.SelectorOffset.ToString(CultureInfo.InvariantCulture)}<br>packet +{sample.PacketOffset.ToString(CultureInfo.InvariantCulture)}; payload bytes {sample.PayloadBytes.ToString(CultureInfo.InvariantCulture)}<br>window `{FormatEmptyHex(sample.HeaderWindowHex)}`";
    }

    private static string FormatSelectorFfRepeatListHeaderSampleShape(Protocol03SelectorFfRepeatListHeaderSample sample)
    {
        return $"{FormatProtocol03NullableU16Field(sample.Entry1FieldHex)} -> {FormatProtocol03NullableU16Field(sample.Entry2EffectiveFieldHex)} ({FormatTableText(sample.Entry2EffectiveFieldSource)}) -> `{FormatEmptyHex(sample.ContinuationPrefixHex)}` -> {FormatProtocol03NullableU16Field(sample.PostMarkerFirstFieldHex)}";
    }

    private static string FormatSelectorFfRepeatListHeaderSamplePosition(Protocol03SelectorFfRepeatListHeaderSample sample)
    {
        return $"+{sample.PositionOffset.ToString(CultureInfo.InvariantCulture)} {FormatCoordinate(sample.X)},{FormatCoordinate(sample.Y)},{FormatCoordinate(sample.Z)}<br>`{FormatEmptyHex(sample.PositionHex)}`";
    }

    private static string FormatSelectorFfRepeatListShapeFieldLayouts(Protocol03SelectorFfRepeatListShapeSummary summary)
    {
        return string.Join("<br>", new[]
        {
            $"entry 1: {FormatTableText(summary.Entry1FieldLayoutKind)}",
            $"entry 2: {FormatTableText(summary.Entry2FieldLayoutKind)}",
            $"post: {FormatTableText(summary.PostMarkerFieldLayoutKind)}"
        });
    }

    private static string ClassifyProtocol03SelectorFfRepeatListFieldLayout(string role, int zeroRun, int? fieldOffset, string fieldHex)
    {
        if (fieldOffset is null || string.IsNullOrWhiteSpace(fieldHex))
        {
            return role.Equals("post-marker", StringComparison.OrdinalIgnoreCase)
                ? "no post-marker u16"
                : "no u16 field";
        }

        if (!role.Equals("post-marker", StringComparison.OrdinalIgnoreCase))
        {
            if (fieldOffset == 1 && fieldHex.StartsWith("ff", StringComparison.OrdinalIgnoreCase))
            {
                return "marker-adjacent entry u16";
            }

            return zeroRun switch
            {
                0 => "immediate entry u16",
                >= 8 => "long-zero-padded entry u16",
                _ => "zero-padded entry u16"
            };
        }

        return zeroRun switch
        {
            0 => "immediate post-marker u16",
            4 => "four-zero post-marker u16",
            >= 8 => "long-zero post-marker u16",
            _ => "zero-padded post-marker u16"
        };
    }

    private static AttributeMatchCount CountEntityMatches(
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates,
        Func<Protocol03NamedProfileRecordCandidate, int?> packetValue,
        IReadOnlyList<WorldEntityEntry> rows,
        Func<WorldEntityEntry, int?> rowValue)
    {
        int comparable = 0;
        int matches = 0;
        foreach (Protocol03NamedProfileRecordCandidate candidate in candidates)
        {
            int? decoded = packetValue(candidate);
            if (decoded is null || !rows.Any(row => rowValue(row) is not null))
            {
                continue;
            }

            comparable++;
            if (rows.Any(row => rowValue(row) == decoded))
            {
                matches++;
            }
        }

        return new AttributeMatchCount(matches, comparable);
    }

    private static AttributeMatchCount CountHealthMatches(
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates,
        IReadOnlyList<WorldEntityEntry> rows)
    {
        int comparable = 0;
        int matches = 0;
        foreach (Protocol03NamedProfileRecordCandidate candidate in candidates)
        {
            int? health = TryReadAttributeUInt16(candidate, 47);
            int? maxHealth = TryReadAttributeUInt16(candidate, 53);
            if (health is null || maxHealth is null || !rows.Any(row => row.Health is not null || row.MaxHealth is not null))
            {
                continue;
            }

            comparable++;
            if (rows.Any(row => (row.Health is null || row.Health == health) && (row.MaxHealth is null || row.MaxHealth == maxHealth)))
            {
                matches++;
            }
        }

        return new AttributeMatchCount(matches, comparable);
    }

    private static AttributeMatchCount CountDescriptionMatches(
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates,
        IReadOnlyList<WorldEntityEntry> rows)
    {
        string[] rowRsiValues = rows
            .Select(row => NormalizeHex(row.Rsi))
            .Where(value => value is not null)
            .Select(value => value!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (rowRsiValues.Length == 0)
        {
            return new AttributeMatchCount(0, 0);
        }

        int comparable = 0;
        int matches = 0;
        foreach (Protocol03NamedProfileRecordCandidate candidate in candidates)
        {
            string? description = NormalizeHex(TryGetAttributeHex(candidate, 21) ?? TryGetAttributeHex(candidate, 11));
            if (description is null)
            {
                continue;
            }

            comparable++;
            if (rowRsiValues.Contains(description, StringComparer.OrdinalIgnoreCase))
            {
                matches++;
            }
        }

        return new AttributeMatchCount(matches, comparable);
    }

    private static PositionMatchSummary SummarizeNearestPositions(
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates,
        IReadOnlyList<WorldEntityEntry> rows)
    {
        WorldEntityEntry[] positionedRows = rows
            .Where(row => row.X is not null && row.Y is not null && row.Z is not null)
            .ToArray();
        if (positionedRows.Length == 0)
        {
            return new PositionMatchSummary(0, 0, 0, 0, 0, null);
        }

        int comparable = 0;
        int exactMatches = 0;
        int within1000 = 0;
        int within2500 = 0;
        int within5000 = 0;
        List<double> nearestDistances = new();
        foreach (Protocol03NamedProfileRecordCandidate candidate in candidates)
        {
            Vector3d? position = TryReadAttributeVector3d(candidate, 27);
            if (position is null)
            {
                continue;
            }

            comparable++;
            double nearest = positionedRows
                .Select(row => Distance(position.Value, new Vector3d(row.X!.Value, row.Y!.Value, row.Z!.Value)))
                .Min();
            nearestDistances.Add(nearest);
            if (nearest < 0.001)
            {
                exactMatches++;
            }

            if (nearest <= 1000)
            {
                within1000++;
            }

            if (nearest <= 2500)
            {
                within2500++;
            }

            if (nearest <= 5000)
            {
                within5000++;
            }
        }

        return new PositionMatchSummary(
            comparable,
            exactMatches,
            within1000,
            within2500,
            within5000,
            Median(nearestDistances));
    }

    private static AttributeMatchCount CountCurrentStateMatches(
        IReadOnlyList<Protocol03NamedProfileRecordCandidate> candidates,
        IReadOnlyList<WorldEntityEntry> rows)
    {
        string[] rowStates = rows
            .Select(row => NormalizeHex(row.CurrentStateHex))
            .Where(value => value is not null)
            .Select(value => value!)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (rowStates.Length == 0)
        {
            return new AttributeMatchCount(0, 0);
        }

        int comparable = 0;
        int matches = 0;
        foreach (Protocol03NamedProfileRecordCandidate candidate in candidates)
        {
            string? state = NormalizeHex(TryGetAttributeHex(candidate, 54));
            if (state is null)
            {
                continue;
            }

            comparable++;
            if (rowStates.Contains(state, StringComparer.OrdinalIgnoreCase))
            {
                matches++;
            }
        }

        return new AttributeMatchCount(matches, comparable);
    }

    private static string FormatMatchCount(AttributeMatchCount count)
    {
        return count.Comparable == 0
            ? "-"
            : $"{count.Matches}/{count.Comparable}";
    }

    private static AttributeMatchCount SumMatchCounts(IEnumerable<AttributeMatchCount> counts)
    {
        int matches = 0;
        int comparable = 0;
        foreach (AttributeMatchCount count in counts)
        {
            matches += count.Matches;
            comparable += count.Comparable;
        }

        return new AttributeMatchCount(matches, comparable);
    }

    private static PositionMatchSummary SumPositionSummaries(IEnumerable<PositionMatchSummary> summaries)
    {
        int comparable = 0;
        int exactMatches = 0;
        int within1000 = 0;
        int within2500 = 0;
        int within5000 = 0;
        foreach (PositionMatchSummary summary in summaries)
        {
            comparable += summary.Comparable;
            exactMatches += summary.ExactMatches;
            within1000 += summary.Within1000;
            within2500 += summary.Within2500;
            within5000 += summary.Within5000;
        }

        return new PositionMatchSummary(comparable, exactMatches, within1000, within2500, within5000, null);
    }

    private static string FormatPositionExact(PositionMatchSummary summary)
    {
        return summary.Comparable == 0
            ? "-"
            : $"{summary.ExactMatches}/{summary.Comparable}";
    }

    private static string FormatPositionWithin(PositionMatchSummary summary, int radius)
    {
        if (summary.Comparable == 0)
        {
            return "-";
        }

        int matches = radius switch
        {
            1000 => summary.Within1000,
            2500 => summary.Within2500,
            5000 => summary.Within5000,
            _ => 0
        };
        return $"{matches}/{summary.Comparable}";
    }

    private static double? Median(IReadOnlyList<double> values)
    {
        if (values.Count == 0)
        {
            return null;
        }

        double[] sorted = values.OrderBy(value => value).ToArray();
        int middle = sorted.Length / 2;
        return sorted.Length % 2 == 0
            ? (sorted[middle - 1] + sorted[middle]) / 2
            : sorted[middle];
    }

    private static string? FormatNpcBaseDecodedSummary(Protocol03NamedProfileRecordCandidate candidate)
    {
        List<string> parts = new();
        if (TryReadAttributeByte(candidate, 45) is int level)
        {
            parts.Add($"L{level}");
        }

        int? health = TryReadAttributeUInt16(candidate, 47);
        int? maxHealth = TryReadAttributeUInt16(candidate, 53);
        if (health is not null && maxHealth is not null)
        {
            parts.Add($"HP{health}/{maxHealth}");
        }

        string? description = NormalizeHex(TryGetAttributeHex(candidate, 21) ?? TryGetAttributeHex(candidate, 11));
        if (description is not null)
        {
            parts.Add($"RSI {description}");
        }

        if (TryReadAttributeByte(candidate, 36) is int npcRank)
        {
            parts.Add($"rank {npcRank}");
        }

        if (TryReadAttributeByte(candidate, 50) is int debuffState)
        {
            parts.Add($"debuff {debuffState}");
        }

        string? currentState = NormalizeHex(TryGetAttributeHex(candidate, 54));
        if (currentState is not null)
        {
            parts.Add($"state {currentState}");
        }

        if (TryReadAttributeVector3d(candidate, 27) is Vector3d position)
        {
            parts.Add($"pos {FormatCoordinate(position.X)},{FormatCoordinate(position.Y)},{FormatCoordinate(position.Z)}");
        }

        return parts.Count == 0 ? null : string.Join(" ", parts);
    }

    private static string? FormatPlayerCharacterCreationSummary(
        Protocol03PlayerCharacterCreationRecord record,
        IReadOnlyDictionary<uint, AbilityDefinition> abilitiesById)
    {
        List<string> parts = new();
        string? firstName = TryDecodeAttributeAscii(record.CreationAttributes, 11);
        string? lastName = TryDecodeAttributeAscii(record.CreationAttributes, 3);
        if (firstName is not null || lastName is not null)
        {
            parts.Add($"name {string.Join(" ", new[] { firstName, lastName }.Where(value => value is not null))}");
        }

        if (TryDecodeAttributeAscii(record.CreationAttributes, 37) is string characterName)
        {
            parts.Add($"handle {characterName}");
        }

        if (TryReadAttributeByte(record.CreationAttributes, 52) is int level)
        {
            parts.Add($"L{level}");
        }

        int? health = TryReadAttributeUInt16(record.CreationAttributes, 41);
        int? maxHealth = TryReadAttributeUInt16(record.CreationAttributes, 24);
        if (health is not null && maxHealth is not null)
        {
            parts.Add($"HP{health}/{maxHealth}");
        }

        string? rsiDescription = NormalizeHex(TryGetAttributeHex(record.CreationAttributes, 47));
        if (rsiDescription is not null)
        {
            parts.Add($"RSI {rsiDescription}");
        }

        if (TryReadAttributeByte(record.CreationAttributes, 53) is int combatantMode)
        {
            parts.Add($"mode {combatantMode}");
        }

        AppendAbilityAttribute(parts, "title", record.CreationAttributes, 42, abilitiesById);
        AppendAbilityAttribute(parts, "cancel", record.CreationAttributes, 9, abilitiesById);
        AppendAbilityAttribute(parts, "exclusive", record.CreationAttributes, 62, abilitiesById);
        AppendAbilityAttribute(parts, "combat exclusive", record.CreationAttributes, 73, abilitiesById);

        if (TryReadAttributeVector3d(record.CreationAttributes, 49) is Vector3d position)
        {
            parts.Add($"pos {FormatCoordinate(position.X)},{FormatCoordinate(position.Y)},{FormatCoordinate(position.Z)}");
        }

        return parts.Count == 0 ? null : string.Join(" ", parts);
    }

    private static void AppendAbilityAttribute(
        List<string> parts,
        string label,
        IReadOnlyList<Protocol03CreationAttributeSample> attributes,
        int index,
        IReadOnlyDictionary<uint, AbilityDefinition> abilitiesById)
    {
        if (TryReadAttributeUInt32(attributes, index) is not uint abilityId || abilityId == 0)
        {
            return;
        }

        parts.Add($"{label} {FormatAbilityReference(abilityId, abilitiesById)}");
    }

    private static string FormatAttributeSignature(IReadOnlyList<Protocol03CreationAttributeSample> attributes)
    {
        string[] signature = attributes
            .Select(attribute => $"{attribute.Index} {FormatTableText(attribute.Name)}")
            .ToArray();
        return FormatCandidateList(signature);
    }

    private static string? FormatSelfViewAttributeSummary(Protocol03SelfViewAttributeLead lead)
    {
        string[] values = lead.Attributes
            .Select(attribute => $"{attribute.Name}={FormatSelfViewAttributeValue(attribute)}")
            .ToArray();
        return values.Length == 0 ? null : string.Join(" ", values);
    }

    private static string FormatSelfViewAttributeValue(Protocol03CreationAttributeSample attribute)
    {
        byte[] bytes = ParseHexBytes(attribute.ValueHex);
        if (bytes.Length == 1)
        {
            return bytes[0].ToString(CultureInfo.InvariantCulture);
        }

        if (bytes.Length == 2)
        {
            return BinaryPrimitives.ReadUInt16LittleEndian(bytes).ToString(CultureInfo.InvariantCulture);
        }

        if (attribute.Name.Equals("Position", StringComparison.OrdinalIgnoreCase) && bytes.Length == 24)
        {
            Vector3d position = new(
                ReadDoubleLittleEndian(bytes, 0),
                ReadDoubleLittleEndian(bytes, 8),
                ReadDoubleLittleEndian(bytes, 16));
            return $"{FormatCoordinate(position.X)},{FormatCoordinate(position.Y)},{FormatCoordinate(position.Z)}";
        }

        return NormalizeHex(attribute.ValueHex) ?? attribute.ValueHex;
    }

    private static string FormatSelfViewSymbolLeads(
        IEnumerable<Protocol03SelfViewAttributeLead> leads,
        IReadOnlyDictionary<string, FxDefinition> fxByHex,
        ILookup<int, GameObjectEntry> gameObjectsById,
        IReadOnlyDictionary<uint, ItemCommandEntry> itemsById)
    {
        List<string> symbols = new();
        foreach (Protocol03SelfViewAttributeLead lead in leads)
        {
            foreach (int fxIndex in new[] { 32, 34 })
            {
                string? hex = NormalizeHex(TryGetAttributeHex(lead.Attributes, fxIndex));
                if (hex is not null && fxByHex.TryGetValue(hex, out FxDefinition? fx))
                {
                    symbols.Add($"{FormatTableText(lead.Attributes.First(attribute => attribute.Index == fxIndex).Name)} `{hex}` {FormatTableText(fx.Name)}");
                }
            }

            if (TryReadAttributeUInt32(lead.Attributes, 31) is uint itemId)
            {
                string[] objectSymbols = gameObjectsById[unchecked((int)itemId)]
                    .Select(entry => FormatTableText(entry.CodeName))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .Take(3)
                    .ToArray();
                if (objectSymbols.Length > 0)
                {
                    symbols.Add($"EquippedItemID `{itemId}` {string.Join(", ", objectSymbols)}");
                }

                if (itemsById.ContainsKey(itemId))
                {
                    symbols.Add($"EquippedItemID {FormatItemReference(itemId, itemsById)}");
                }
            }
        }

        string[] distinct = symbols
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
            .Take(8)
            .ToArray();
        return FormatCandidateList(distinct);
    }

    private static string? TryGetAttributeHex(Protocol03NamedProfileRecordCandidate candidate, int index)
    {
        return TryGetAttributeHex(candidate.CreationAttributes, index);
    }

    private static string? TryGetAttributeHex(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        return attributes.FirstOrDefault(attribute => attribute.Index == index)?.ValueHex;
    }

    private static string? TryDecodeAttributeAscii(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        byte[] bytes = ParseHexBytes(TryGetAttributeHex(attributes, index));
        int textLength = Array.FindIndex(bytes, value => value == 0);
        if (textLength < 0)
        {
            textLength = bytes.Length;
        }

        if (textLength == 0 || bytes.Take(textLength).Any(value => value < 0x20 || value > 0x7e))
        {
            return null;
        }

        string text = Encoding.ASCII.GetString(bytes, 0, textLength).Trim();
        return string.IsNullOrWhiteSpace(text) || !text.Any(char.IsLetter) ? null : text;
    }

    private static int? TryReadAttributeByte(Protocol03NamedProfileRecordCandidate candidate, int index)
    {
        return TryReadAttributeByte(candidate.CreationAttributes, index);
    }

    private static int? TryReadAttributeByte(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        byte[] bytes = ParseHexBytes(TryGetAttributeHex(attributes, index));
        return bytes.Length == 1 ? bytes[0] : null;
    }

    private static int? TryReadAttributeUInt16(Protocol03NamedProfileRecordCandidate candidate, int index)
    {
        return TryReadAttributeUInt16(candidate.CreationAttributes, index);
    }

    private static int? TryReadAttributeUInt16(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        byte[] bytes = ParseHexBytes(TryGetAttributeHex(attributes, index));
        return bytes.Length == 2 ? BinaryPrimitives.ReadUInt16LittleEndian(bytes) : null;
    }

    private static uint? TryReadAttributeUInt32(Protocol03NamedProfileRecordCandidate candidate, int index)
    {
        return TryReadAttributeUInt32(candidate.CreationAttributes, index);
    }

    private static uint? TryReadAttributeUInt32(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        byte[] bytes = ParseHexBytes(TryGetAttributeHex(attributes, index));
        return bytes.Length == 4 ? BinaryPrimitives.ReadUInt32LittleEndian(bytes) : null;
    }

    private static Vector3d? TryReadAttributeVector3d(Protocol03NamedProfileRecordCandidate candidate, int index)
    {
        return TryReadAttributeVector3d(candidate.CreationAttributes, index);
    }

    private static Vector3d? TryReadAttributeVector3d(IReadOnlyList<Protocol03CreationAttributeSample> attributes, int index)
    {
        byte[] bytes = ParseHexBytes(TryGetAttributeHex(attributes, index));
        if (bytes.Length != 24)
        {
            return null;
        }

        return new Vector3d(
            ReadDoubleLittleEndian(bytes, 0),
            ReadDoubleLittleEndian(bytes, 8),
            ReadDoubleLittleEndian(bytes, 16));
    }

    private static double ReadDoubleLittleEndian(byte[] bytes, int offset)
    {
        long bits = BinaryPrimitives.ReadInt64LittleEndian(bytes.AsSpan(offset, 8));
        return BitConverter.Int64BitsToDouble(bits);
    }

    private static double Distance(Vector3d left, Vector3d right)
    {
        double x = left.X - right.X;
        double y = left.Y - right.Y;
        double z = left.Z - right.Z;
        return Math.Sqrt(x * x + y * y + z * z);
    }

    private static byte[] ParseHexBytes(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return Array.Empty<byte>();
        }

        return value
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(part => byte.TryParse(part, NumberStyles.HexNumber, CultureInfo.InvariantCulture, out byte result) ? result : (byte)0)
            .ToArray();
    }

    private static string? NormalizeHex(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        string normalized = value.Replace(" ", string.Empty, StringComparison.Ordinal).Trim().ToLowerInvariant();
        return normalized.Length == 0 ? null : normalized;
    }

    private static string FormatCoordinate(double value)
    {
        double rounded = Math.Round(value);
        return Math.Abs(value - rounded) < 0.001
            ? rounded.ToString(CultureInfo.InvariantCulture)
            : value.ToString("0.###", CultureInfo.InvariantCulture);
    }

    private static string FormatEntryIds(IEnumerable<int> values)
    {
        int[] distinct = values
            .Distinct()
            .OrderBy(value => value)
            .ToArray();
        if (distinct.Length == 0)
        {
            return "-";
        }

        List<string> ranges = new();
        int start = distinct[0];
        int previous = distinct[0];
        for (int i = 1; i < distinct.Length; i++)
        {
            if (distinct[i] == previous + 1)
            {
                previous = distinct[i];
                continue;
            }

            ranges.Add(start == previous
                ? start.ToString(CultureInfo.InvariantCulture)
                : $"{start.ToString(CultureInfo.InvariantCulture)}-{previous.ToString(CultureInfo.InvariantCulture)}");
            start = previous = distinct[i];
        }

        ranges.Add(start == previous
            ? start.ToString(CultureInfo.InvariantCulture)
            : $"{start.ToString(CultureInfo.InvariantCulture)}-{previous.ToString(CultureInfo.InvariantCulture)}");
        return string.Join("<br>", ranges.Take(8));
    }

    private static string FormatDistance(double? value)
    {
        if (value is null)
        {
            return "-";
        }

        double rounded = Math.Round(value.Value);
        return Math.Abs(value.Value - rounded) < 0.001
            ? rounded.ToString(CultureInfo.InvariantCulture)
            : value.Value.ToString("0.#", CultureInfo.InvariantCulture);
    }

