    private static string FormatNestedMovementPosition(Protocol03NestedMovementLead lead)
    {
        return $"{FormatCoordinate(lead.X)},{FormatCoordinate(lead.Y)},{FormatCoordinate(lead.Z)}";
    }

    private static string FormatMovementStateTailFamily(Protocol03MovementStateTailLead lead)
    {
        if (lead.MarkerHex.StartsWith("ff 01", StringComparison.OrdinalIgnoreCase))
        {
            return $"variable selector + 3-byte tag + {lead.MarkerHex}";
        }

        if (lead.MarkerHex.Equals("80 80", StringComparison.OrdinalIgnoreCase))
        {
            return "variable selector + 3-byte tag + 80 80";
        }

        return $"selector {lead.TailSelector} + {FormatEmptyHex(lead.PrefixHex)}";
    }

    private static string FormatMovementStateTailTagRange(IEnumerable<Protocol03MovementStateTailLeadWithFile> leads)
    {
        uint[] values = leads.Select(entry => entry.Lead.TagValue).ToArray();
        if (values.Length == 0)
        {
            return "-";
        }

        uint min = values.Min();
        uint max = values.Max();
        string minHex = min.ToString("x8", CultureInfo.InvariantCulture);
        string maxHex = max.ToString("x8", CultureInfo.InvariantCulture);
        return min == max ? $"`{minHex}`" : $"`{minHex}`..`{maxHex}`";
    }

    private static string FormatMovementStateTailTagDeltas(IEnumerable<Protocol03MovementStateTailLeadWithFile> leads)
    {
        List<string> deltas = new();
        foreach (var group in leads.GroupBy(entry => entry.File, StringComparer.OrdinalIgnoreCase))
        {
            Protocol03MovementStateTailLeadWithFile[] ordered = group
                .OrderBy(entry => entry.Line)
                .ToArray();
            for (int i = 1; i < ordered.Length; i++)
            {
                long delta = (long)ordered[i].Lead.TagValue - ordered[i - 1].Lead.TagValue;
                if (delta > 0)
                {
                    deltas.Add(delta.ToString(CultureInfo.InvariantCulture));
                }
            }
        }

        return FormatDistinct(deltas, 8);
    }

    private static string FormatEmptyHex(string value)
    {
        return string.IsNullOrWhiteSpace(value) ? "-" : value;
    }

    private static string FormatCountSummary(IEnumerable<string> values)
    {
        return FormatCountSummary(values, int.MaxValue);
    }

    private static string FormatCountSummary(IEnumerable<string> values, int maxValues)
    {
        string[] parts = values
            .Where(value => !string.IsNullOrWhiteSpace(value))
            .GroupBy(value => value, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key, StringComparer.OrdinalIgnoreCase)
            .Select(group => $"{group.Key} ({group.Count()})")
            .ToArray();
        if (parts.Length == 0)
        {
            return "-";
        }

        return parts.Length <= maxValues
            ? string.Join("; ", parts)
            : $"{string.Join("; ", parts.Take(maxValues))}; +{parts.Length - maxValues} more";
    }

    private static string FormatManageBonusCountDictionary(IReadOnlyDictionary<string, int> values, string separator = "; ")
    {
        return values.Count == 0
            ? "-"
            : string.Join(separator, values.Select(entry => $"{entry.Key} ({entry.Value})"));
    }

    private static string FormatManageBonusStateFieldReference(ManageBonusStateIdLongFormFieldLeadSummary lead)
    {
        string references = lead.FieldReferences.Count == 0
            ? "no local reference"
            : string.Join("; ", lead.FieldReferences.Select(FormatTableText));
        return $"`{lead.Field1}` ({lead.Field1Value}) {references} ({lead.PayloadCount})";
    }

    private static string FormatManageBonusSemanticFamilySample(ManageBonusStateIdLongFormSemanticFamilySummary summary)
    {
        string references = summary.SampleFieldReferences.Count == 0
            ? "no local reference"
            : string.Join("; ", summary.SampleFieldReferences.Select(FormatTableText));
        return $"`{summary.SampleField0}/{summary.SampleField1}` ({summary.SampleField1Value}) {references}; `{summary.SampleFile}:{summary.SampleLine}`";
    }

    private static string FormatManageBonusTradeStateSample(ManageBonusTradeStateValueSummary summary)
    {
        return $"`{summary.SampleFile}:{summary.SampleLine}` `{summary.SamplePayloadHex}`";
    }

    private static bool IsThreeByteZeroTailPreHeader(string value)
    {
        return TryReadThreeByteZeroTailPreHeaderValue(value) is not null;
    }

    private static int? TryReadThreeByteZeroTailPreHeaderValue(string value)
    {
        byte[] bytes = ParseHexBytes(value);
        return bytes.Length == 3 && bytes[1] == 0 && bytes[2] == 0 ? bytes[0] : null;
    }

    private static string ClassifyProtocol03DynamicCreationTailPrefix(string value)
    {
        byte[] bytes = ParseHexBytes(value);
        if (bytes.Length >= 8 &&
            bytes[1] == 0x00 &&
            bytes[2] == 0x00 &&
            bytes[3] == 0x01 &&
            bytes[4] == 0x00 &&
            bytes[5] == 0x0c &&
            bytes[6] == 0x57 &&
            bytes[7] == 0x02)
        {
            return "next dynamic object-view boundary";
        }

        if (bytes.Length == 5 &&
            bytes[1] == 0x00 &&
            bytes[2] == 0x00 &&
            bytes[3] == 0x00 &&
            bytes[4] == 0x00)
        {
            return "five-byte zero tail lead";
        }

        if (bytes.Length >= 6 &&
            bytes[1] == 0x00 &&
            bytes[2] == 0x00 &&
            bytes[3] == 0x00 &&
            bytes[4] == 0x00 &&
            bytes[5] == 0x04 &&
            ContainsBytePair(bytes, 0x16, 0x80))
        {
            return "zero-extended 04/16 80 tail lead";
        }

        if (bytes.Length >= 2 && bytes[0] == 0x02 && bytes[1] == 0x03 && ContainsBytePair(bytes, 0x16, 0x80))
        {
            return "02 03/16 80 tail lead";
        }

        if (!string.IsNullOrEmpty(FormatProtocol03DynamicTailHeaderLikeLeads(value)))
        {
            return "header-like object-view tail lead";
        }

        if (ContainsBytePair(bytes, 0x16, 0x80))
        {
            return "16 80-bearing tail lead";
        }

        return "other tail lead";
    }

    private static string FormatProtocol03DynamicTailHeaderLikeLeads(string value)
    {
        string[] leads = EnumerateProtocol03DynamicTailHeaderLikeLeadInfos(value)
            .Select(lead => lead.Label)
            .ToArray();
        return leads.Length == 0 ? string.Empty : string.Join("<br>", leads);
    }

    private static IEnumerable<string> EnumerateProtocol03DynamicTailHeaderLikeLeads(string value)
    {
        return EnumerateProtocol03DynamicTailHeaderLikeLeadInfos(value).Select(lead => lead.Label);
    }

    private static IEnumerable<Protocol03DynamicTailHeaderLikeLead> EnumerateProtocol03DynamicTailHeaderLikeLeadInfos(string value)
    {
        byte[] bytes = ParseHexBytes(value);
        int maxCandidate = Math.Min(8, bytes.Length - 4);
        for (int offset = 0; offset <= maxCandidate; offset++)
        {
            if (!IsProtocol03DynamicTailHeaderLikeOffset(bytes, offset))
            {
                continue;
            }

            int viewId = bytes[offset] | (bytes[offset + 1] << 8);
            byte updateCount = bytes[offset + 2];
            byte firstSelector = bytes[offset + 3];
            if (viewId == 0 || updateCount == 0 || updateCount > 0x20)
            {
                continue;
            }

            yield return new Protocol03DynamicTailHeaderLikeLead(offset, viewId, updateCount, firstSelector);
        }
    }

    private static string FormatProtocol03DynamicTailBodyHints(string value, Protocol03DynamicTailHeaderLikeLead lead)
    {
        byte[] bytes = ParseHexBytes(value);
        int bodyOffset = lead.Offset + 4;
        if (bodyOffset >= bytes.Length)
        {
            return "-";
        }

        List<string> hints = new()
        {
            $"body {FormatHexBytes(bytes.Skip(bodyOffset).Take(Math.Min(8, bytes.Length - bodyOffset)))}"
        };

        string[] separators = EnumerateBytePairOffsets(bytes, bodyOffset, 0xcd, 0xab)
            .Take(3)
            .Select(offset => $"cd ab @+{offset - bodyOffset}")
            .ToArray();
        if (separators.Length > 0)
        {
            hints.Add(string.Join(", ", separators));
        }

        string[] positions = EnumerateProtocol03DynamicTailFloat3Hints(bytes, bodyOffset)
            .Take(3)
            .ToArray();
        if (positions.Length > 0)
        {
            hints.Add(string.Join(", ", positions));
        }

        return string.Join("; ", hints);
    }

    private static bool TryCreateProtocol03DynamicTailBodyAnchor(
        Protocol03NamedProfileRecordCandidate candidate,
        Protocol03DynamicTailHeaderLikeLead lead,
        out Protocol03DynamicTailBodyAnchor? anchor)
    {
        byte[] bytes = ParseHexBytes(candidate.PostCreationObjectViewDynamicTailPrefixHex);
        int bodyOffset = lead.Offset + 4;
        if (bodyOffset >= bytes.Length)
        {
            anchor = null;
            return false;
        }

        foreach (int separatorOffset in EnumerateBytePairOffsets(bytes, bodyOffset, 0xcd, 0xab))
        {
            string bodyPrefixHex = FormatHexBytes(bytes.Skip(bodyOffset).Take(separatorOffset - bodyOffset));
            string postSeparatorPrefixHex = FormatHexBytes(bytes.Skip(separatorOffset).Take(Math.Min(8, bytes.Length - separatorOffset)));
            anchor = new Protocol03DynamicTailBodyAnchor(
                candidate,
                lead,
                separatorOffset - bodyOffset,
                bodyPrefixHex,
                postSeparatorPrefixHex);
            return true;
        }

        anchor = null;
        return false;
    }

    private static IEnumerable<int> EnumerateBytePairOffsets(IReadOnlyList<byte> bytes, int offset, byte first, byte second)
    {
        for (int i = Math.Max(0, offset); i + 1 < bytes.Count; i++)
        {
            if (bytes[i] == first && bytes[i + 1] == second)
            {
                yield return i;
            }
        }
    }

    private static IEnumerable<string> EnumerateProtocol03DynamicTailFloat3Hints(byte[] bytes, int bodyOffset)
    {
        int maxOffset = Math.Min(bytes.Length - 12, bodyOffset + 20);
        for (int offset = bodyOffset; offset <= maxOffset; offset++)
        {
            float x = ReadSingleLittleEndian(bytes, offset);
            float y = ReadSingleLittleEndian(bytes, offset + 4);
            float z = ReadSingleLittleEndian(bytes, offset + 8);
            if (!IsPlausibleProtocol03Position(x, y, z))
            {
                continue;
            }

            yield return $"float3 @+{offset - bodyOffset} {FormatCoordinate(x)},{FormatCoordinate(y)},{FormatCoordinate(z)}";
        }
    }

    private static float ReadSingleLittleEndian(byte[] bytes, int offset)
    {
        int bits = BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(offset, 4));
        return BitConverter.Int32BitsToSingle(bits);
    }

    private static string FormatHexBytes(IEnumerable<byte> bytes)
    {
        return string.Join(" ", bytes.Select(value => value.ToString("x2", CultureInfo.InvariantCulture)));
    }

    private static bool IsPlausibleProtocol03Position(float x, float y, float z)
    {
        return float.IsFinite(x) &&
            float.IsFinite(y) &&
            float.IsFinite(z) &&
            Math.Abs(x) < 100000 &&
            Math.Abs(y) < 5000 &&
            Math.Abs(z) < 100000 &&
            CountMeaningfulProtocol03PositionAxes(x, y, z) >= 2;
    }

    private static int CountMeaningfulProtocol03PositionAxes(float x, float y, float z)
    {
        int axes = 0;
        if (Math.Abs(x) >= 1000)
        {
            axes++;
        }

        if (Math.Abs(y) >= 100)
        {
            axes++;
        }

        if (Math.Abs(z) >= 1000)
        {
            axes++;
        }

        return axes;
    }

    private static bool IsProtocol03DynamicTailHeaderLikeOffset(IReadOnlyList<byte> bytes, int offset)
    {
        return offset switch
        {
            0 => true,
            3 => bytes.Count > 2 && bytes[1] == 0x00 && bytes[2] == 0x00,
            4 => bytes.Count > 3 && bytes[1] == 0x00 && bytes[2] == 0x00 && bytes[3] == 0x00,
            7 => bytes.Count > 6 &&
                bytes[1] == 0x00 &&
                bytes[2] == 0x00 &&
                bytes[3] == 0x01 &&
                bytes[4] == 0x00 &&
                bytes[5] == 0x08 &&
                bytes[6] == 0x50 &&
                offset + 3 < bytes.Count &&
                bytes[offset + 3] == 0x80,
            _ => false
        };
    }

    private static bool ContainsBytePair(IReadOnlyList<byte> bytes, byte first, byte second)
    {
        for (int i = 0; i + 1 < bytes.Count; i++)
        {
            if (bytes[i] == first && bytes[i + 1] == second)
            {
                return true;
            }
        }

        return false;
    }

    private static string FormatStaticObjectPosition(StaticObjectEntry entry)
    {
        return $"{entry.MetrId}/{entry.SectorId} {FormatCoordinate(entry.X)},{FormatCoordinate(entry.Y)},{FormatCoordinate(entry.Z)} type {entry.TypeId}";
    }

    private static string? FormatStaticObjectQuaternion(Protocol03StaticObjectLead lead)
    {
        if (lead.Q0 is null || lead.Q1 is null || lead.Q2 is null || lead.Q3 is null)
        {
            return null;
        }

        return $"{FormatCoordinate(lead.Q0.Value)},{FormatCoordinate(lead.Q1.Value)},{FormatCoordinate(lead.Q2.Value)},{FormatCoordinate(lead.Q3.Value)}";
    }

    private static string? FormatStaticObjectPostQuaternionVector(Protocol03StaticObjectLead lead)
    {
        if (lead.PostQuaternionX is null || lead.PostQuaternionY is null || lead.PostQuaternionZ is null)
        {
            return null;
        }

        return $"{FormatCoordinate(lead.PostQuaternionX.Value)},{FormatCoordinate(lead.PostQuaternionY.Value)},{FormatCoordinate(lead.PostQuaternionZ.Value)}";
    }

    private static string? FormatStaticObjectNearestDistance(Protocol03StaticObjectLead lead, IReadOnlyList<StaticObjectEntry> staticRows)
    {
        if (lead.PostQuaternionX is null || lead.PostQuaternionY is null || lead.PostQuaternionZ is null || staticRows.Count == 0)
        {
            return null;
        }

        Vector3d vector = new(lead.PostQuaternionX.Value, lead.PostQuaternionY.Value, lead.PostQuaternionZ.Value);
        double nearest = staticRows
            .Select(entry => Distance(vector, new Vector3d(entry.X, entry.Y, entry.Z)))
            .Min();
        return FormatDistance(nearest);
    }

    private static string? FormatStaticObjectTailField(string fieldHex, uint? value)
    {
        return value is null || string.IsNullOrWhiteSpace(fieldHex)
            ? null
            : $"{value.Value} ({fieldHex})";
    }

    private static string FormatStaticTypeSymbols(
        IReadOnlyList<StaticObjectEntry> staticRows,
        ILookup<int, GameObjectEntry> gameObjectsById)
    {
        if (staticRows.Count == 0)
        {
            return "-";
        }

        string[] symbols = staticRows
            .GroupBy(entry => entry.TypeId)
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Select(group =>
            {
                string[] names = gameObjectsById[group.Key]
                    .Select(entry => FormatTableText(entry.CodeName))
                    .Distinct(StringComparer.OrdinalIgnoreCase)
                    .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
                    .Take(3)
                    .ToArray();
                string symbolText = names.Length == 0
                    ? "-"
                    : string.Join(", ", names);
                return $"{group.Key} {symbolText} ({group.Count()})";
            })
            .ToArray();
        return FormatCandidateList(symbols);
    }

    private static string FormatFxMatchSummary(IReadOnlyList<FxMatch> matches)
    {
        if (matches.Count == 0)
        {
            return "-";
        }

        string[] summaries = matches
            .GroupBy(match => new
            {
                match.Hex,
                match.Name
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.Hex, StringComparer.OrdinalIgnoreCase)
            .Take(5)
            .Select(group => $"`{group.Key.Hex}` {FormatTableText(group.Key.Name)} ({group.Count()})")
            .ToArray();
        return FormatCandidateList(summaries);
    }

    private static string? FormatWorldEntityScope(WorldEntityEntry entry)
    {
        if (!string.IsNullOrWhiteSpace(entry.Zone) && !string.IsNullOrWhiteSpace(entry.Kind))
        {
            return $"{entry.Zone} / {entry.Kind}";
        }

        return !string.IsNullOrWhiteSpace(entry.Zone)
            ? entry.Zone
            : entry.Kind;
    }

    private static string FormatDominantManageBonusLayout(IReadOnlyList<PayloadWithFile> payloads)
    {
        if (payloads.Count == 0)
        {
            return "-";
        }

        var group = payloads
            .GroupBy(entry => new
            {
                Byte9Field = PayloadWordAtByteOffset(entry.Payload.PayloadHex, 9),
                Byte11Value = PayloadWordAtByteOffset(entry.Payload.PayloadHex, 11),
                Byte15Value = PayloadWordAtByteOffset(entry.Payload.PayloadHex, 15)
            })
            .OrderByDescending(group => group.Count())
            .ThenBy(group => group.Key.Byte9Field, StringComparer.OrdinalIgnoreCase)
            .First();

        return $"`{group.Key.Byte9Field}` / `{group.Key.Byte11Value}` / `{group.Key.Byte15Value}` ({group.Count()})";
    }

    private static string PayloadWordAtByteOffset(string payloadHex, int byteOffset)
    {
        string[] bytes = payloadHex.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return byteOffset >= 0 && byteOffset + 1 < bytes.Length
            ? $"{bytes[byteOffset]} {bytes[byteOffset + 1]}"
            : "-";
    }

    private static string PayloadBytesAtByteOffset(string payloadHex, int byteOffset, int byteCount)
    {
        string[] bytes = payloadHex.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return byteOffset >= 0 && byteCount > 0 && byteOffset + byteCount <= bytes.Length
            ? string.Join(" ", bytes.Skip(byteOffset).Take(byteCount))
            : "-";
    }

    private static string FormatPacketCaptureScope(string file)
    {
        string normalized = file.Replace('\\', '/');
        if (normalized.Contains("/actions/", StringComparison.OrdinalIgnoreCase))
        {
            return "actions";
        }

        if (normalized.Contains("/teleport/", StringComparison.OrdinalIgnoreCase))
        {
            return "teleport";
        }

        if (normalized.Contains("/logins/", StringComparison.OrdinalIgnoreCase))
        {
            return "logins";
        }

        if (normalized.Contains("/abilities/", StringComparison.OrdinalIgnoreCase))
        {
            return "abilities";
        }

        if (normalized.Contains("/movement/", StringComparison.OrdinalIgnoreCase))
        {
            return "movement";
        }

        if (normalized.Contains("/others/", StringComparison.OrdinalIgnoreCase))
        {
            return "others";
        }

        if (normalized.Contains("/trinitys/proxy_second_pc/", StringComparison.OrdinalIgnoreCase))
        {
            return "inventory proxy";
        }

        if (normalized.Contains("doors", StringComparison.OrdinalIgnoreCase))
        {
            return "doors";
        }

        return Path.GetFileName(normalized);
    }

    private static bool TryGetProtocol04Sequence(
        IReadOnlyDictionary<PacketLocation, Protocol04PacketSequenceSample> sequencesByPacket,
        PayloadWithFile entry,
        out Protocol04PacketSequenceSample? sequence)
    {
        return sequencesByPacket.TryGetValue(new PacketLocation(entry.File, entry.Payload.Line), out sequence);
    }

    private static bool HasAnyProtocol04Header(Protocol04PacketSequenceSample? sequence, params string[] headers)
    {
        if (sequence is null)
        {
            return false;
        }

        return sequence.Headers.Any(header => headers.Contains(header, StringComparer.OrdinalIgnoreCase));
    }

    private static bool IsInteractionCaptureContext(string file)
    {
        return FormatInteractionCaptureScope(file) != "other";
    }

    private static string FormatInteractionCaptureScope(string file)
    {
        string normalized = file.Replace('\\', '/');

        if (ContainsAnyIgnoreCase(normalized, "vendor", "merchant", "market", "shop", "buy", "sell", "buyed"))
        {
            return "vendor/market";
        }

        if (ContainsAnyIgnoreCase(normalized, "trade"))
        {
            return "trade";
        }

        if (ContainsAnyIgnoreCase(normalized, "inventory", "inv_"))
        {
            return "inventory";
        }

        if (ContainsAnyIgnoreCase(normalized, "loot"))
        {
            return "loot";
        }

        if (ContainsAnyIgnoreCase(normalized, "hardline", "doors", "door", "static"))
        {
            return "static interaction";
        }

        if (ContainsAnyIgnoreCase(normalized, "npc", "mission", "collector", "archivist"))
        {
            return "npc/mission";
        }

        if (ContainsAnyIgnoreCase(normalized, "actions", "interaction", "two-person", "2_person"))
        {
            return "interaction";
        }

        if (ContainsAnyIgnoreCase(normalized, "combat", "ability"))
        {
            return "combat/ability";
        }

        return "other";
    }

    private static bool ContainsAnyIgnoreCase(string value, params string[] terms)
    {
        return terms.Any(term => value.Contains(term, StringComparison.OrdinalIgnoreCase));
    }

    private static bool HasManageBonusFieldAttributeCandidate(IReadOnlyList<AttributeDefinition> attributes, int fieldValue)
    {
        return attributes.Any(attribute =>
            (attribute.CreationIndex == fieldValue || attribute.UpdateIndex == fieldValue) &&
            IsInteractionAttributeName(attribute.AttributeName));
    }

    private static string FormatManageBonusSemanticFieldReference(
        int fieldValue,
        string fieldHex,
        int count,
        IReadOnlyList<AttributeDefinition> attributes,
        ILookup<int, GameObjectEntry> gameObjectsById)
    {
        List<string> references = new();
        references.AddRange(SemanticAttributeCandidates(attributes, fieldValue, creationIndex: true)
            .Take(2)
            .Select(candidate => $"creation {candidate}"));
        references.AddRange(SemanticAttributeCandidates(attributes, fieldValue, creationIndex: false)
            .Take(2)
            .Select(candidate => $"update {candidate}"));
        references.AddRange(gameObjectsById[fieldValue]
            .Select(entry => $"go {entry.CodeName}")
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(value => value, StringComparer.OrdinalIgnoreCase)
            .Take(2));

        string referenceText = references.Count == 0
            ? "no local reference"
            : string.Join("; ", references.Select(FormatTableText));
        return $"`{fieldHex}` ({fieldValue}) {referenceText} ({count})";
    }

    private static string[] SemanticAttributeCandidates(
        IReadOnlyList<AttributeDefinition> attributes,
        int fieldValue,
        bool creationIndex)
    {
        return attributes
            .Where(attribute => creationIndex ? attribute.CreationIndex == fieldValue : attribute.UpdateIndex == fieldValue)
            .GroupBy(attribute => attribute.AttributeName, StringComparer.OrdinalIgnoreCase)
            .OrderByDescending(group => IsInteractionAttributeName(group.Key))
            .ThenByDescending(group => group.Count())
            .ThenBy(group => group.Key)
            .Take(8)
            .Select(group => $"{group.Key} ({group.Count()})")
            .ToArray();
    }

    private static string[] ClassifyManageBonusSemanticFamily(
        int payloadCount,
        int byte9RepeatCount,
        int byte11RepeatCount,
        int samePacketB2Matches,
        int samePacketB3Matches,
        int samePacketVendorOrMarket,
        int interactionCandidatePayloads)
    {
        List<string> inference = new();
        if (byte9RepeatCount == payloadCount && (samePacketB2Matches > 0 || samePacketB3Matches > 0))
        {
            inference.Add("state-id long-form candidate");
        }
        else if (byte9RepeatCount * 10 >= payloadCount * 8)
        {
            inference.Add("field1 self-repeat schema");
        }

        if (samePacketB2Matches > 0)
        {
            inference.Add("links to 80 b2 short state");
        }

        if (samePacketB3Matches > 0)
        {
            inference.Add("links to 80 b3 unload state");
        }

        if (samePacketVendorOrMarket > 0)
        {
            inference.Add("vendor/market co-packet context");
        }

        if (interactionCandidatePayloads > 0)
        {
            inference.Add("interaction attribute-index candidates");
        }

        if (byte11RepeatCount > 0 && byte11RepeatCount * 2 >= payloadCount)
        {
            inference.Add("field2 value mirror schema");
        }

        return inference.Count == 0
            ? new[] { "state-bundle shape" }
            : inference.ToArray();
    }

    private static bool IsInteractionAttributeName(string name)
    {
        string[] terms =
        {
            "buy",
            "sell",
            "vendor",
            "shop",
            "merchant",
            "talk",
            "giver",
            "taker",
            "putactive",
            "use",
            "trade",
            "loot",
            "market",
            "inventory",
            "active",
            "interaction",
            "currentstate"
        };

        return terms.Any(term => name.Contains(term, StringComparison.OrdinalIgnoreCase));
    }

    private static Dictionary<string, FxDefinition> BuildFxDictionary(IReadOnlyList<FxDefinition> fxDefinitions)
    {
        Dictionary<string, FxDefinition> fxByHex = new(StringComparer.OrdinalIgnoreCase);
        foreach (FxDefinition fx in fxDefinitions)
        {
            fxByHex.TryAdd(fx.LittleEndianHex, fx);
            fxByHex.TryAdd(fx.BigEndianHex, fx);
        }

        return fxByHex;
    }

    private static Dictionary<uint, ItemCommandEntry> BuildItemCommandDictionary(IReadOnlyList<ItemCommandEntry> itemCommandEntries)
    {
        Dictionary<uint, ItemCommandEntry> itemsById = new();
        foreach (ItemCommandEntry entry in itemCommandEntries)
        {
            itemsById.TryAdd(entry.ItemId, entry);
        }

        return itemsById;
    }

    private static Dictionary<uint, VendorPriceEntry> BuildVendorPriceDictionary(IReadOnlyList<VendorPriceEntry> vendorPriceEntries)
    {
        Dictionary<uint, VendorPriceEntry> pricesByGoId = new();
        foreach (VendorPriceEntry entry in vendorPriceEntries)
        {
            pricesByGoId.TryAdd(entry.GoId, entry);
        }

        return pricesByGoId;
    }

    private static Dictionary<uint, AbilityDefinition> BuildAbilityDefinitionDictionary(IReadOnlyList<AbilityDefinition> abilityDefinitions)
    {
        Dictionary<uint, AbilityDefinition> abilitiesById = new();
        foreach (AbilityDefinition entry in abilityDefinitions)
        {
            abilitiesById.TryAdd(entry.AbilityId, entry);
        }

        return abilitiesById;
    }

    private static IEnumerable<FxMatch> FindFxMatches(string file, ManageBonusPayloadSample payload, IReadOnlyDictionary<string, FxDefinition> fxByHex)
    {
        return FindFxMatches(file, payload.Line, payload.PayloadHex, fxByHex);
    }

    private static IEnumerable<FxMatch> FindFxMatches(string file, int line, string payloadHex, IReadOnlyDictionary<string, FxDefinition> fxByHex)
    {
        string[] bytes = payloadHex.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        for (int offset = 0; offset <= bytes.Length - 4; offset++)
        {
            string hex = string.Concat(bytes.Skip(offset).Take(4)).ToLowerInvariant();
            if (fxByHex.TryGetValue(hex, out FxDefinition? fx))
            {
                yield return new FxMatch(file, line, offset, hex, fx.Name, payloadHex);
            }
        }
    }

    private static FxMatch? FindFxMatchAtOffset(string file, int line, string payloadHex, IReadOnlyDictionary<string, FxDefinition> fxByHex, int offset)
    {
        string[] bytes = payloadHex.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        if (offset < 0 || offset > bytes.Length - 4)
        {
            return null;
        }

        string hex = string.Concat(bytes.Skip(offset).Take(4)).ToLowerInvariant();
        return fxByHex.TryGetValue(hex, out FxDefinition? fx)
            ? new FxMatch(file, line, offset, hex, fx.Name, payloadHex)
            : null;
    }

    private static string FormatList(IReadOnlyList<string> values)
    {
        return values.Count == 0
            ? "`none`"
            : string.Join(", ", values.Select(value => $"`{value}`"));
    }

    private static string FormatSourceLocation(string file, int line)
    {
        return $"{Path.GetFileName(file)}:{line}";
    }

    private static string FormatSequence(IReadOnlyList<string> headers)
    {
        List<string> runs = new();
        for (int i = 0; i < headers.Count;)
        {
            string header = headers[i];
            int count = 1;
            while (i + count < headers.Count && headers[i + count].Equals(header, StringComparison.OrdinalIgnoreCase))
            {
                count++;
            }

            runs.Add(count == 1 ? header : $"{header} x{count}");
            i += count;
        }

        return string.Join(" -> ", runs);
    }

    private static string FormatBoolean(bool value)
    {
        return value ? "yes" : "no";
    }

